static void check_owned(char *got, const char *want, int line)
{
	test_check_str(got, want, "result", __FILE__, line);
	free(got);
}

#define CHECK_OWNED(got, want) check_owned((got), (want), __LINE__)

static char *repeat(const char *head, int c, size_t n, const char *tail)
{
	size_t h, t;
	char *s;

	h = strlen(head);
	t = strlen(tail);
	s = xmalloc(h + n + t + 1);
	memcpy(s, head, h);
	memset(s + h, c, n);
	memcpy(s + h + n, tail, t + 1);
	return s;
}

static void write_file(const char *dir, const char *name, const char *text)
{
	char *path;
	FILE *fp;

	path = xjoin(dir, name);
	fp = fopen(path, "w");
	if (fp == NULL) {
		printf("cannot create %s: %s\n", path, strerror(errno));
		exit(1);
	}
	fputs(text, fp);
	fclose(fp);
	free(path);
}

static char *make_dir(const char *parent, const char *name)
{
	char *path;

	path = xjoin(parent, name);
	if (mkdir(path, 0777) != 0 && errno != EEXIST) {
		printf("cannot create %s: %s\n", path, strerror(errno));
		exit(1);
	}
	return path;
}

static void test_encode(void)
{
	char *path, *out;

	CHECK_OWNED(path_encode("/Users/m/my.repo"), "-Users-m-my-repo");
	CHECK_OWNED(path_encode("/a b/c_d~e"), "-a-b-c-d-e");
	/* Each UTF-16 unit is one dash: four letters, a space, a surrogate pair. */
	CHECK_OWNED(path_encode("/Users/m/Za\xc5\xbc\xc3\xb3\xc5\x82\xc4\x87 "
	    "\xf0\x9f\x99\x82"), "-Users-m-Za-------");
	CHECK_OWNED(path_encode("/x\xff"), "-x-");

	/* Expected hashes computed from Claude Code's algorithm (CLAUDE.md). */
	path = repeat("/", 'b', 199, "");
	out = path_encode(path);
	CHECK(strlen(out) == 200);
	CHECK(strchr(out + 1, '-') == NULL);
	free(out);
	free(path);

	path = repeat("/", 'b', 200, "");
	out = path_encode(path);
	CHECK(strlen(out) == 207);
	CHECK_STR(out + 200, "-86ms41");
	CHECK(strncmp(out, "-bbb", 4) == 0);
	free(out);
	free(path);

	path = repeat("/", 'c', 201, "");
	out = path_encode(path);
	CHECK_STR(out + 200, "-id6lpo");
	free(out);
	free(path);

	path = repeat("/Users/m/", 'x', 200, "/repo");
	out = path_encode(path);
	CHECK_STR(out + 200, "-tmrojt");
	CHECK(strncmp(out, "-Users-m-xxx", 12) == 0);
	free(out);
	free(path);

	path = repeat("/Users/m/Za\xc5\xbc\xc3\xb3\xc5\x82\xc4\x87 "
	    "g\xc4\x99\xc5\x9bl\xc4\x85 ja\xc5\xba\xc5\x84/", 'a', 190,
	    "/\xf0\x9f\x99\x82");
	out = path_encode(path);
	CHECK_STR(out + 200, "-6v8qh5");
	free(out);
	free(path);
}

static void test_normalize(void)
{
	CHECK_OWNED(path_normalize("/a//b/./c/../d/"), "/a/b/d");
	CHECK_OWNED(path_normalize("/.."), "/");
	CHECK_OWNED(path_normalize("/"), "/");
	CHECK_OWNED(path_normalize("/a/b/../../.."), "/");
	CHECK_OWNED(path_normalize("/a/.b/..c"), "/a/.b/..c");
}

/*
 * work/dir with space is real, work/link points at it: the 3.1 trap,
 * a symlink into a directory whose name has a space.
 */
static void test_logical_physical(void)
{
	char *real, *link, *expect, *file, *got;

	real = make_dir(work, "dir with space");
	free(make_dir(real, "sub"));
	link = xjoin(work, "link");
	if (symlink("dir with space", link) != 0 && errno != EEXIST) {
		printf("cannot create %s: %s\n", link, strerror(errno));
		exit(1);
	}
	write_file(real, "file", "");

	CHECK(chdir(link) == 0);
	setenv("PWD", link, 1);
	expect = xjoin(link, "x");
	CHECK_OWNED(path_logical("sub/../x"), expect);
	free(expect);
	CHECK_OWNED(path_logical("."), link);
	CHECK_OWNED(path_logical("/abs/./p/"), "/abs/p");

	/* A stale $PWD is ignored in favour of the physical directory. */
	setenv("PWD", work, 1);
	expect = xjoin(real, "x");
	CHECK_OWNED(path_logical("x"), expect);
	free(expect);
	setenv("PWD", "relative", 1);
	expect = xjoin(real, "x");
	CHECK_OWNED(path_logical("x"), expect);
	free(expect);

	CHECK_OWNED(path_physical("."), real);
	CHECK_OWNED(path_physical(link), real);
	expect = xjoin(real, "sub");
	CHECK_OWNED(path_physical("sub"), expect);
	free(expect);

	/* Missing parts are appended to the deepest existing ancestor. */
	got = xjoin(link, "new/deeper/");
	expect = xjoin(real, "new/deeper");
	CHECK_OWNED(path_physical(got), expect);
	free(got);
	free(expect);
	got = xjoin(link, "new/../sub/x");
	expect = xjoin(real, "sub/x");
	CHECK_OWNED(path_physical(got), expect);
	free(got);
	free(expect);
	file = xjoin(link, "file/x");
	expect = xjoin(real, "file/x");
	CHECK_OWNED(path_physical(file), expect);
	free(file);
	free(expect);

	CHECK(chdir(work) == 0);
	free(real);
	free(link);
}

static void test_prefix(void)
{
	CHECK(path_has_prefix("/a/repo", "/a/repo"));
	CHECK(path_has_prefix("/a/repo/x", "/a/repo"));
	CHECK(path_has_prefix("/a/repo/x", "/a/repo/"));
	CHECK(!path_has_prefix("/a/repo2", "/a/repo"));
	CHECK(!path_has_prefix("/a/rep", "/a/repo"));
	CHECK(!path_has_prefix("/a", "/a/repo"));
	CHECK(path_has_prefix("/x", "/"));
}

static void test_path_parts(void)
{
	static const struct path_pair pairs[] = {
		{ "/a/link/repo", "/b/repo" },
		{ "/a/real/repo", "/b/real/repo" }
	};

	CHECK_OWNED(path_move("/a/repo/x", "/a/repo", "/b", 0), "/b/x");
	CHECK_OWNED(path_move("/a/repo", "/a/repo/", "/b/", 0), "/b");
	CHECK_OWNED(path_move("/a/repo2", "/a/repo", "/b", 0), NULL);
	CHECK_OWNED(path_move("/a/repo", "/a/repo", "/b", 1), NULL);
	CHECK_OWNED(path_move("/a", "/a", "/", 0), "/");

	CHECK_OWNED(rewrite_project_path(pairs, 2, "/a/link/repo/sub"),
	    "/b/repo/sub");
	CHECK_OWNED(rewrite_project_path(pairs, 2, "/a/real/repo"),
	    "/b/real/repo");
	CHECK_OWNED(rewrite_project_path(pairs, 2, "/a/real/repo2"), NULL);

	CHECK_OWNED(path_tilde("/Users/m/x", "/Users/m"), "~/x");
	CHECK_OWNED(path_tilde("/Users/m", "/Users/m/"), "~");
	CHECK_OWNED(path_tilde("/Users/mm/x", "/Users/m"), "/Users/mm/x");
	CHECK_OWNED(path_tilde("/x", "/"), "/x");
	CHECK_OWNED(path_tilde("/x", NULL), "/x");

	CHECK_OWNED(path_base("/a/b/"), "b");
	CHECK_OWNED(path_base("/a"), "a");
	CHECK_OWNED(path_base("/"), "/");
	CHECK_OWNED(path_dir("/a/b/"), "/a");
	CHECK_OWNED(path_dir("/a"), "/");
	CHECK_OWNED(path_dir("a"), ".");
}

/*
 * A process known by argv[0] only, as the native Claude Code: started
 * through the symlink "claude", the kernel names it after the version
 * file. The sleeper ends by itself and is waited for, never stopped.
 */
static void test_process_argv0(void)
{
	struct timespec pause = { 0, 10000000 };
	pid_t pid;
	int i, found = 0, status;

	if (sleeper == NULL || access(sleeper, X_OK) != 0) {
		printf("unit: no build/csm-fake-claude, argv[0] check skipped\n");
		return;
	}
	pid = fork();
	if (pid == 0) {
		execl(sleeper, "csm-argv0-test", "1", (char *)NULL);
		_exit(127);
	}
	CHECK(pid > 0);
	if (pid <= 0)
		return;
	for (i = 0; i < 100 && !found; i++) {
		found = platform_process_running("csm-argv0-test") == 1;
		if (!found)
			nanosleep(&pause, NULL);
	}
	CHECK(found);
	CHECK(platform_process_running("csm-argv0-tes") == 0);
	CHECK(waitpid(pid, &status, 0) == pid && WIFEXITED(status) &&
	    WEXITSTATUS(status) == 0);
	CHECK(platform_process_running("csm-argv0-test") == 0);
}

/* The test binary itself runs as "unit" (cut to the kernel's length). */
static void test_process(void)
{
	CHECK(platform_process_running("unit") == 1);
	CHECK(platform_process_running("csm-no-such-process") == 0);

	setenv("CSM_CLAUDE_PROCESS", "unit", 1);
	CHECK(claude_running() == 1);
	setenv("CSM_CLAUDE_PROCESS", "csm-no-such-process", 1);
	CHECK(claude_running() == 0);
	unsetenv("CSM_CLAUDE_PROCESS");
	test_process_argv0();
}

static char *decode(const char *s)
{
	return json_decode_string(s, strlen(s));
}

static void test_json(void)
{
	CHECK_OWNED(decode("a\\\"b\\\\c"), "a\"b\\c");
	CHECK_OWNED(decode("\\/Users\\/m"), "/Users/m");
	CHECK_OWNED(decode("\\b\\f\\n\\r\\t"), "\b\f\n\r\t");
	CHECK_OWNED(decode("\\u0105\\u00F3"), "\xc4\x85\xc3\xb3");
	CHECK_OWNED(decode("\\ud83d\\ude42"), "\xf0\x9f\x99\x82");
	CHECK_OWNED(decode("\\ud83dx"), "\xef\xbf\xbdx");
	CHECK_OWNED(decode("\\ude42"), "\xef\xbf\xbd");
	CHECK_OWNED(decode("\xc4\x85"), "\xc4\x85");
	CHECK_OWNED(decode(""), "");
	CHECK_OWNED(decode("\\x"), NULL);
	CHECK_OWNED(decode("\\u12"), NULL);
	CHECK_OWNED(decode("a\tb"), NULL);
	CHECK_OWNED(decode("\\"), NULL);

	CHECK_OWNED(json_top_string("{\"type\":\"user\",\"message\":"
	    "{\"cwd\":\"/nested\"},\"cwd\":\"/top\"}", "cwd"), "/top");
	CHECK_OWNED(json_top_string(" { \"a\" : [1, {\"cwd\":\"x\"}, true, null] , "
	    "\"cwd\" : \"\\/p\\u0105\" }\n", "cwd"), "/p\xc4\x85");
	CHECK_OWNED(json_top_string("{\"x\":\"a\\\"cwd\\\":\\\"b\",\"cwd\":\"/c\"}",
	    "cwd"), "/c");
	CHECK_OWNED(json_top_string("{\"c\\u0077d\":\"/esc\"}", "cwd"), "/esc");
	CHECK_OWNED(json_top_string("{\"cwd\":5}", "cwd"), NULL);
	CHECK_OWNED(json_top_string("{\"x\":\"y\"}", "cwd"), NULL);
	CHECK_OWNED(json_top_string("{}", "cwd"), NULL);
	CHECK_OWNED(json_top_string("[1]", "cwd"), NULL);
	CHECK_OWNED(json_top_string("{\"cwd\":\"/a", "cwd"), NULL);
	CHECK_OWNED(json_top_string("{\"a\":{\"b\":1,\"cwd\":\"/c\"", "cwd"), NULL);
	CHECK_OWNED(json_top_string("", "cwd"), NULL);
	CHECK_OWNED(json_top_string("{\"cwd\":\"/a\",\"cwd\":\"/b\"}", "cwd"), "/b");
}

static void ignore_token(const struct json_token *tok, void *ctx)
{
	(void)tok;
	(void)ctx;
}

static int scan_ok(const char *s, size_t len)
{
	return json_scan(s, len, ignore_token, NULL) == 0;
}

#define SCAN_OK(s) scan_ok((s), sizeof(s) - 1)

struct token_log {
	const char *text;
	char buf[1024];
};

/* One line per token: kind (k for keys), path, raw bytes. */
static void log_token(const struct json_token *tok, void *ctx)
{
	static const char kinds[] = "snloa";
	struct token_log *log = ctx;
	char *p;
	size_t i;

	p = log->buf + strlen(log->buf);
	*p++ = tok->is_key ? 'k' : kinds[tok->kind];
	*p++ = ' ';
	for (i = 0; i < tok->depth; i++) {
		if (tok->path[i].key != NULL)
			p += sprintf(p, "/%s", tok->path[i].key);
		else
			p += sprintf(p, "/%zu", tok->path[i].index);
	}
	sprintf(p, " %.*s\n", (int)(tok->end - tok->start),
	    log->text + tok->start);
}

static void test_json_scan(void)
{
	struct token_log log;

	CHECK(SCAN_OK("{}"));
	CHECK(SCAN_OK(" [ ] "));
	CHECK(SCAN_OK("\"s\""));
	CHECK(SCAN_OK("0"));
	CHECK(SCAN_OK("{\"a\":[1,-0.5e+3,2E7,true,false,null,\"x\\u0105\"]}\n"));
	CHECK(SCAN_OK("{\"a\":{\"b\":[[{}]]}}"));
	CHECK(SCAN_OK("{\"a\":1,\"a\":2}"));
	CHECK(!SCAN_OK(""));
	CHECK(!SCAN_OK("  "));
	CHECK(!SCAN_OK("{"));
	CHECK(!SCAN_OK("["));
	CHECK(!SCAN_OK("{\"a\"}"));
	CHECK(!SCAN_OK("{\"a\":1,}"));
	CHECK(!SCAN_OK("[1,]"));
	CHECK(!SCAN_OK("[1 2]"));
	CHECK(!SCAN_OK("{a:1}"));
	CHECK(!SCAN_OK("01"));
	CHECK(!SCAN_OK("1."));
	CHECK(!SCAN_OK("-"));
	CHECK(!SCAN_OK("1e"));
	CHECK(!SCAN_OK("tru"));
	CHECK(!SCAN_OK("nulls"));
	CHECK(!SCAN_OK("{\"a\":1}x"));
	CHECK(!SCAN_OK("{} {}"));
	CHECK(!SCAN_OK("\"\\x\""));
	CHECK(!SCAN_OK("\"a\tb\""));
	CHECK(!SCAN_OK("\"\\u12\""));
	CHECK(!SCAN_OK("\"abc"));
	CHECK(!SCAN_OK("[1,\0]"));
	CHECK(!SCAN_OK("[1]]"));

	log.text = "{\"a\":[1,{\"b\":\"x\"}],\"c\":true}";
	log.buf[0] = '\0';
	CHECK(json_scan(log.text, strlen(log.text), log_token, &log) == 0);
	CHECK_STR(log.buf,
	    "k /a \"a\"\n"
	    "n /a/0 1\n"
	    "k /a/1/b \"b\"\n"
	    "s /a/1/b \"x\"\n"
	    "o /a/1 {\"b\":\"x\"}\n"
	    "a /a [1,{\"b\":\"x\"}]\n"
	    "k /c \"c\"\n"
	    "l /c true\n"
	    "o  {\"a\":[1,{\"b\":\"x\"}],\"c\":true}\n");

	log.text = " [ \"\\u0061\" , [ ] ] ";
	log.buf[0] = '\0';
	CHECK(json_scan(log.text, strlen(log.text), log_token, &log) == 0);
	CHECK_STR(log.buf,
	    "s /0 \"\\u0061\"\n"
	    "a /1 [ ]\n"
	    "a  [ \"\\u0061\" , [ ] ]\n");
}

static void test_json_encode(void)
{
	const char *samples[] = {
		"/Users/m/repo", "a\"b\\c", "\b\f\n\r\t\x01\x1f",
		"Za\xc5\xbc\xc3\xb3\xc5\x82\xc4\x87 \xf0\x9f\x99\x82", ""
	};
	char *enc;
	size_t i;

	CHECK_OWNED(json_encode_string("/a/b"), "/a/b");
	CHECK_OWNED(json_encode_string("a\"b\\c"), "a\\\"b\\\\c");
	CHECK_OWNED(json_encode_string("\n\t\x01\x7f"), "\\n\\t\\u0001\x7f");
	CHECK_OWNED(json_encode_string("\xc4\x85"), "\xc4\x85");
	for (i = 0; i < sizeof samples / sizeof samples[0]; i++) {
		enc = json_encode_string(samples[i]);
		CHECK_OWNED(json_decode_string(enc, strlen(enc)), samples[i]);
		free(enc);
	}
}

static const struct path_pair test_pairs[] = {
	{ "/L/old/repo", "/L/new/repo" },
	{ "/P/old/repo", "/P/new/repo" }
};

static const struct rewrite_rules test_rules = {
	test_pairs, 2, "/h/projects/-L-old-repo", "/h/projects/-L-new-repo"
};

/* The rewritten text, or NULL when nothing changes. */
static char *rw(enum rewrite_kind kind, const char *text,
    struct change_list *plan)
{
	char *out;
	size_t len;

	rewrite_text(text, strlen(text), kind, &test_rules, "f", 7, plan, &out,
	    &len);
	return out;
}

static void check_change(const struct change_list *plan, size_t i,
    enum change_kind kind, const char *field, const char *old_value,
    const char *new_value, int line)
{
	const struct change *c;

	test_check(i < plan->count, "change exists", __FILE__, line);
	if (i >= plan->count)
		return;
	c = &plan->items[i];
	test_check(c->kind == kind, "change kind", __FILE__, line);
	test_check_str(c->field, field, "field", __FILE__, line);
	test_check_str(c->old_value, old_value, "old value", __FILE__, line);
	test_check_str(c->new_value, new_value, "new value", __FILE__, line);
}

#define CHECK_CHANGE(plan, i, kind, field, old_value, new_value) \
	check_change((plan), (i), (kind), (field), (old_value), (new_value), \
	    __LINE__)

static void test_rewrite_session(void)
{
	struct change_list plan = { NULL, 0, 0 };
	char *out;
	size_t len;

	CHECK_OWNED(rw(REWRITE_SESSION,
	    "{\"type\":\"user\",\"cwd\":\"/L/old/repo\",\"x\":1}", &plan),
	    "{\"type\":\"user\",\"cwd\":\"/L/new/repo\",\"x\":1}");
	CHECK(plan.count == 1 && plan.items[0].line == 7);
	CHECK(plan.count == 1 && strcmp(plan.items[0].file, "f") == 0);
	CHECK_CHANGE(&plan, 0, CHANGE_REWRITE, "cwd", "/L/old/repo",
	    "/L/new/repo");
	change_list_free(&plan);

	CHECK_OWNED(rw(REWRITE_SESSION, "{\"cwd\":\"/L/old/repo/src\"}", NULL),
	    "{\"cwd\":\"/L/new/repo/src\"}");
	CHECK_OWNED(rw(REWRITE_SESSION, "{\"cwd\":\"/P/old/repo\"}", NULL),
	    "{\"cwd\":\"/P/new/repo\"}");
	CHECK_OWNED(rw(REWRITE_SESSION, "{\"cwd\":\"/L/old/repo2\"}", NULL), NULL);
	CHECK_OWNED(rw(REWRITE_SESSION, "{\"cwd\":\"/elsewhere\"}", NULL), NULL);
	CHECK_OWNED(rw(REWRITE_SESSION, "{\"message\":{\"cwd\":\"/L/old/repo\"},"
	    "\"cwd\":\"/x\"}", NULL), NULL);
	CHECK_OWNED(rw(REWRITE_SESSION, "{\"/L/old/repo\":1}", NULL), NULL);
	CHECK_OWNED(rw(REWRITE_SESSION, "[\"/L/old/repo\"]", NULL), NULL);
	CHECK_OWNED(rw(REWRITE_SESSION, "{\"type\":\"relocated\",\"sessionId\":"
	    "\"s\",\"relocatedCwd\":\"/L/old/repo\"}", NULL),
	    "{\"type\":\"relocated\",\"sessionId\":\"s\",\"relocatedCwd\":"
	    "\"/L/new/repo\"}");
	/* Only the changed value is encoded again. */
	CHECK_OWNED(rw(REWRITE_SESSION, "{\"cwd\":\"\\/L\\/old\\/repo\\/\\u0105\","
	    "\"note\":\"\\/keep\"}", NULL),
	    "{\"cwd\":\"/L/new/repo/\xc4\x85\",\"note\":\"\\/keep\"}");
	CHECK_OWNED(rw(REWRITE_SESSION, "{ \"cwd\" : \"/L/old/repo\" , \"a\" : "
	    "[ 1 ] }\r", NULL), "{ \"cwd\" : \"/L/new/repo\" , \"a\" : [ 1 ] }\r");

	CHECK_OWNED(rw(REWRITE_SESSION, "{\"toolUseResult\":{"
	    "\"persistedOutputPath\":\"/h/projects/-L-old-repo/s/tool-results/a\"}}",
	    &plan), "{\"toolUseResult\":{\"persistedOutputPath\":"
	    "\"/h/projects/-L-new-repo/s/tool-results/a\"}}");
	CHECK_CHANGE(&plan, 0, CHANGE_REWRITE,
	    "toolUseResult.persistedOutputPath",
	    "/h/projects/-L-old-repo/s/tool-results/a",
	    "/h/projects/-L-new-repo/s/tool-results/a");
	change_list_free(&plan);
	CHECK_OWNED(rw(REWRITE_SESSION, "{\"p\":\"/h/projects/-L-old-repo\"}",
	    NULL), NULL);
	CHECK_OWNED(rw(REWRITE_SESSION, "{\"p\":\"/h/projects/-L-old-repo2/a\"}",
	    NULL), NULL);
	CHECK_OWNED(rw(REWRITE_SESSION, "{\"a\":[{\"b\":"
	    "\"/h/projects/-L-old-repo/x\"}]}", &plan),
	    "{\"a\":[{\"b\":\"/h/projects/-L-new-repo/x\"}]}");
	CHECK_CHANGE(&plan, 0, CHANGE_REWRITE, "a[0].b",
	    "/h/projects/-L-old-repo/x", "/h/projects/-L-new-repo/x");
	change_list_free(&plan);

	/* A cut line changes nothing and plans nothing. */
	CHECK(rewrite_text("{\"cwd\":\"/L/old/repo\",\"x", 23, REWRITE_SESSION,
	    &test_rules, "f", 1, &plan, &out, &len) == REWRITE_INVALID);
	CHECK(out == NULL && plan.count == 0);
}

static void test_rewrite_index(void)
{
	struct change_list plan = { NULL, 0, 0 };

	CHECK_OWNED(rw(REWRITE_INDEX, "{\"version\":1,\"entries\":[{"
	    "\"sessionId\":\"a\",\"fullPath\":\"/h/projects/-L-old-repo/a.jsonl\","
	    "\"projectPath\":\"/L/old/repo\",\"firstPrompt\":\"/L/old/repo\"}],"
	    "\"originalPath\":\"/P/old/repo\"}", &plan),
	    "{\"version\":1,\"entries\":[{"
	    "\"sessionId\":\"a\",\"fullPath\":\"/h/projects/-L-new-repo/a.jsonl\","
	    "\"projectPath\":\"/L/new/repo\",\"firstPrompt\":\"/L/old/repo\"}],"
	    "\"originalPath\":\"/P/new/repo\"}");
	CHECK(plan.count == 3);
	CHECK_CHANGE(&plan, 0, CHANGE_REWRITE, "entries[0].fullPath",
	    "/h/projects/-L-old-repo/a.jsonl", "/h/projects/-L-new-repo/a.jsonl");
	CHECK_CHANGE(&plan, 1, CHANGE_REWRITE, "entries[0].projectPath",
	    "/L/old/repo", "/L/new/repo");
	CHECK_CHANGE(&plan, 2, CHANGE_REWRITE, "originalPath", "/P/old/repo",
	    "/P/new/repo");
	change_list_free(&plan);
	CHECK_OWNED(rw(REWRITE_INDEX, "{\"projectPath\":\"/L/old/repo\"", NULL),
	    NULL);
}

static void test_rewrite_config(void)
{
	struct change_list plan = { NULL, 0, 0 };
	char *out;
	size_t len;

	CHECK_OWNED(rw(REWRITE_CONFIG,
	    "{\n"
	    "  \"numStartups\": 3,\n"
	    "  \"projects\": {\n"
	    "    \"/L/old/repo\": {\n"
	    "      \"allowedTools\": [],\n"
	    "      \"x\": \"/L/old/repo\"\n"
	    "    },\n"
	    "    \"/L/old/repo/sub\": {},\n"
	    "    \"/L/old/repo2\": {}\n"
	    "  },\n"
	    "  \"githubRepoPaths\": {\n"
	    "    \"o/r\": [\n"
	    "      \"/P/old/repo\",\n"
	    "      \"/x\"\n"
	    "    ]\n"
	    "  },\n"
	    "  \"other\": {\"projects\": {\"/L/old/repo\": 1}}\n"
	    "}\n", &plan),
	    "{\n"
	    "  \"numStartups\": 3,\n"
	    "  \"projects\": {\n"
	    "    \"/L/new/repo\": {\n"
	    "      \"allowedTools\": [],\n"
	    "      \"x\": \"/L/old/repo\"\n"
	    "    },\n"
	    "    \"/L/new/repo/sub\": {},\n"
	    "    \"/L/old/repo2\": {}\n"
	    "  },\n"
	    "  \"githubRepoPaths\": {\n"
	    "    \"o/r\": [\n"
	    "      \"/P/new/repo\",\n"
	    "      \"/x\"\n"
	    "    ]\n"
	    "  },\n"
	    "  \"other\": {\"projects\": {\"/L/old/repo\": 1}}\n"
	    "}\n");
	CHECK(plan.count == 3);
	CHECK_CHANGE(&plan, 0, CHANGE_REWRITE, "projects", "/L/old/repo",
	    "/L/new/repo");
	CHECK_CHANGE(&plan, 1, CHANGE_REWRITE, "projects", "/L/old/repo/sub",
	    "/L/new/repo/sub");
	CHECK_CHANGE(&plan, 2, CHANGE_REWRITE, "githubRepoPaths[\"o/r\"][0]",
	    "/P/old/repo", "/P/new/repo");
	change_list_free(&plan);

	/* The new key exists: the old one stays and is reported. */
	CHECK_OWNED(rw(REWRITE_CONFIG, "{\"projects\":{\"/L/old/repo\":{\"a\":1},"
	    "\"/L/new/repo\":{\"b\":2}}}", &plan), NULL);
	CHECK(plan.count == 1);
	CHECK_CHANGE(&plan, 0, CHANGE_CONFLICT, "projects", "/L/old/repo",
	    "/L/new/repo");
	change_list_free(&plan);
	CHECK_OWNED(rw(REWRITE_CONFIG, "{\"projects\":{\"/L/old/repo/a\":1,"
	    "\"/L/old/repo\":2,\"/L/new/repo/a\":3}}", &plan),
	    "{\"projects\":{\"/L/old/repo/a\":1,\"/L/new/repo\":2,"
	    "\"/L/new/repo/a\":3}}");
	CHECK_CHANGE(&plan, 0, CHANGE_CONFLICT, "projects", "/L/old/repo/a",
	    "/L/new/repo/a");
	CHECK_CHANGE(&plan, 1, CHANGE_REWRITE, "projects", "/L/old/repo",
	    "/L/new/repo");
	change_list_free(&plan);

	/* A moved githubRepoPaths element that would repeat goes. */
	CHECK_OWNED(rw(REWRITE_CONFIG, "{\"githubRepoPaths\":{\"o/r\":["
	    "\"/P/new/repo\",\"/P/old/repo\"]}}", &plan),
	    "{\"githubRepoPaths\":{\"o/r\":[\"/P/new/repo\"]}}");
	CHECK(plan.count == 1);
	CHECK_CHANGE(&plan, 0, CHANGE_REMOVE, "githubRepoPaths[\"o/r\"][1]",
	    "/P/old/repo", NULL);
	change_list_free(&plan);
	CHECK_OWNED(rw(REWRITE_CONFIG, "{\"githubRepoPaths\":{\"o/r\":["
	    "\"/P/old/repo\", \"/P/new/repo\"]}}", NULL),
	    "{\"githubRepoPaths\":{\"o/r\":[\"/P/new/repo\"]}}");
	CHECK_OWNED(rw(REWRITE_CONFIG, "{\"githubRepoPaths\": {\n"
	    "  \"o/r\": [\n    \"/P/old/repo\",\n    \"/P/new/repo\"\n  ]\n}}",
	    NULL), "{\"githubRepoPaths\": {\n"
	    "  \"o/r\": [\n    \"/P/new/repo\"\n  ]\n}}");
	CHECK_OWNED(rw(REWRITE_CONFIG, "{\"githubRepoPaths\":{\"o/r\":["
	    "\"/P/old/repo\",\"/P/old/repo\",\"/x\"]}}", NULL),
	    "{\"githubRepoPaths\":{\"o/r\":[\"/P/new/repo\",\"/x\"]}}");
	CHECK_OWNED(rw(REWRITE_CONFIG, "{\"githubRepoPaths\":{\"o/r\":["
	    "\"/P/old/repo\",\"/P/old/repo\",\"/P/new/repo\"]}}", NULL),
	    "{\"githubRepoPaths\":{\"o/r\":[\"/P/new/repo\"]}}");
	CHECK_OWNED(rw(REWRITE_CONFIG, "{\"githubRepoPaths\":{\"o/r\":["
	    "1,\"/P/old/repo\",\"/P/new/repo\"],\"o/s\":[\"/L/old/repo\"]}}", NULL),
	    "{\"githubRepoPaths\":{\"o/r\":[1,\"/P/new/repo\"],"
	    "\"o/s\":[\"/L/new/repo\"]}}");
	CHECK_OWNED(rw(REWRITE_CONFIG, "{\"githubRepoPaths\":{\"o/r\":["
	    "\"/P/old/repo\",\"/L/old/repo\"]}}", NULL),
	    "{\"githubRepoPaths\":{\"o/r\":[\"/P/new/repo\",\"/L/new/repo\"]}}");
	CHECK_OWNED(rw(REWRITE_CONFIG, "{\"githubRepoPaths\":{\"o/r\":["
	    "\"/x\",\"/P/new/repo\",\"/P/old/repo\",\"/P/old/repo\",\"/y\"]}}",
	    NULL), "{\"githubRepoPaths\":{\"o/r\":[\"/x\",\"/P/new/repo\","
	    "\"/y\"]}}");

	CHECK_OWNED(rw(REWRITE_CONFIG, "[{\"projects\":{\"/L/old/repo\":1}}]",
	    NULL), NULL);
	CHECK(rewrite_text("{\"projects\":{\"/L/old/repo\":{}}", 30,
	    REWRITE_CONFIG, &test_rules, "f", 0, &plan, &out, &len) ==
	    REWRITE_INVALID);
	CHECK(out == NULL && plan.count == 0);
}

static char *read_all(const char *path)
{
	char *data;
	size_t len;

	return file_read(path, &data, &len) == 0 ? data : NULL;
}

#define OLD_SEC 1000000000
#define OLD_NSEC 123456789

static void set_old_times(const char *path)
{
	struct timespec t[2];

	t[0].tv_sec = t[1].tv_sec = OLD_SEC;
	t[0].tv_nsec = t[1].tv_nsec = OLD_NSEC;
	CHECK(utimensat(AT_FDCWD, path, t, 0) == 0);
}

/*
 * Only the modification time: with relatime (the Linux default) reading a
 * file whose access time is not after its modification time updates it,
 * and the test reads the files it checks.
 */
static int has_old_mtime(const char *path)
{
	struct timespec t[2];
	struct stat st;

	if (stat(path, &st) != 0)
		return 0;
	platform_file_times(&st, t);
	return t[1].tv_sec == OLD_SEC && t[1].tv_nsec == OLD_NSEC;
}

static int file_mode(const char *path)
{
	struct stat st;

	return stat(path, &st) == 0 ? (int)(st.st_mode & 07777) : -1;
}

/* Temporary files left behind by the atomic writer. */
static int leftovers(const char *dir)
{
	struct dirent *e;
	DIR *d;
	int n = 0;

	d = opendir(dir);
	if (d == NULL)
		return -1;
	while ((e = readdir(d)) != NULL)
		if (strstr(e->d_name, ".csm-") != NULL)
			n++;
	closedir(d);
	return n;
}

static void test_rewrite_files(void)
{
	static const struct path_pair there[] = {
		{ "/L/new/repo", "/L/third/repo" }
	};
	static const struct path_pair back[] = {
		{ "/L/third/repo", "/L/new/repo" }
	};
	static const struct rewrite_rules rules_there = { there, 1, NULL, NULL };
	static const struct rewrite_rules rules_back = { back, 1, NULL, NULL };
	static const char session[] =
	    "{\"type\":\"mode\"}\n"
	    "{\"type\":\"user\",\"cwd\":\"/L/old/repo\"}\n"
	    "{\"type\":\"x\"}\n"
	    "{\"cwd\":\"/L/old/repo\",\"x";
	static const char config_text[] =
	    "{\n  \"projects\": {\n    \"/L/old/repo\": {}\n  }\n}\n";
	struct change_list plan = { NULL, 0, 0 };
	struct stat st, before;
	char *dir, *file, *other, *index, *config, *bak, *bad, *bad_bak, *missing;
	char *real, *link, *long_text, *long_file;
	int backup_done = 0;

	dir = make_dir(work, "rewrite");

	write_file(dir, "s.jsonl", session);
	file = xjoin(dir, "s.jsonl");
	CHECK(chmod(file, 0640) == 0);
	set_old_times(file);
	CHECK(rewrite_file(file, REWRITE_SESSION, &test_rules, &plan, 0, NULL) ==
	    REWRITE_OK);
	CHECK(plan.count == 1 && plan.items[0].line == 2);
	CHECK_OWNED(read_all(file), session);
	CHECK(has_old_mtime(file));
	change_list_free(&plan);
	CHECK(rewrite_file(file, REWRITE_SESSION, &test_rules, &plan, 1, NULL) ==
	    REWRITE_OK);
	CHECK(plan.count == 1);
	change_list_free(&plan);
	CHECK_OWNED(read_all(file),
	    "{\"type\":\"mode\"}\n"
	    "{\"type\":\"user\",\"cwd\":\"/L/new/repo\"}\n"
	    "{\"type\":\"x\"}\n"
	    "{\"cwd\":\"/L/old/repo\",\"x");
	CHECK(file_mode(file) == 0640);
	CHECK(has_old_mtime(file));

	/* Lines longer than any buffer, the cwd after them. */
	long_text = repeat("{\"text\":\"", 'x', 3 * SESSION_CHUNK,
	    "\"}\n{\"cwd\":\"/P/old/repo\"}\n");
	write_file(dir, "long.jsonl", long_text);
	long_file = xjoin(dir, "long.jsonl");
	CHECK(rewrite_file(long_file, REWRITE_SESSION, &test_rules, NULL, 1,
	    NULL) == REWRITE_OK);
	strcpy(strstr(long_text, "/P/old/repo"), "/P/new/repo\"}\n");
	CHECK_OWNED(read_all(long_file), long_text);
	free(long_text);
	free(long_file);

	/* A file without changes is not written at all. */
	write_file(dir, "o.jsonl", "{\"cwd\":\"/elsewhere\"}\n");
	other = xjoin(dir, "o.jsonl");
	CHECK(stat(other, &before) == 0);
	CHECK(rewrite_file(other, REWRITE_SESSION, &test_rules, &plan, 1, NULL) ==
	    REWRITE_OK);
	CHECK(plan.count == 0);
	CHECK(stat(other, &st) == 0 && st.st_ino == before.st_ino);
	missing = xjoin(dir, "missing.jsonl");
	errno = 0;
	CHECK(rewrite_file(missing, REWRITE_SESSION, &test_rules, &plan, 1,
	    NULL) == REWRITE_ERROR && errno == ENOENT);
	free(missing);

	write_file(dir, "sessions-index.json", "{\"entries\":[{\"fullPath\":"
	    "\"/h/projects/-L-old-repo/a.jsonl\",\"projectPath\":"
	    "\"/L/old/repo\"}]}\n");
	index = xjoin(dir, "sessions-index.json");
	set_old_times(index);
	CHECK(rewrite_file(index, REWRITE_INDEX, &test_rules, NULL, 1, NULL) ==
	    REWRITE_OK);
	CHECK_OWNED(read_all(index), "{\"entries\":[{\"fullPath\":"
	    "\"/h/projects/-L-new-repo/a.jsonl\",\"projectPath\":"
	    "\"/L/new/repo\"}]}\n");
	CHECK(has_old_mtime(index));

	/* .claude.json: a backup on the first change of a run, fresh times. */
	write_file(dir, ".claude.json", config_text);
	config = xjoin(dir, ".claude.json");
	bak = xjoin(dir, ".claude.json.bak");
	CHECK(chmod(config, 0600) == 0);
	set_old_times(config);
	CHECK(rewrite_file(config, REWRITE_CONFIG, &test_rules, &plan, 0,
	    &backup_done) == REWRITE_OK);
	CHECK(plan.count == 1 && backup_done == 0);
	CHECK(access(bak, F_OK) != 0);
	CHECK_OWNED(read_all(config), config_text);
	change_list_free(&plan);
	CHECK(rewrite_file(config, REWRITE_CONFIG, &test_rules, NULL, 1,
	    &backup_done) == REWRITE_OK);
	CHECK(backup_done == 1);
	CHECK_OWNED(read_all(bak), config_text);
	CHECK(has_old_mtime(bak));
	CHECK(file_mode(bak) == 0600);
	CHECK_OWNED(read_all(config),
	    "{\n  \"projects\": {\n    \"/L/new/repo\": {}\n  }\n}\n");
	CHECK(!has_old_mtime(config));
	CHECK(file_mode(config) == 0600);
	CHECK(rewrite_file(config, REWRITE_CONFIG, &rules_there, NULL, 1,
	    &backup_done) == REWRITE_OK);
	CHECK_OWNED(read_all(bak), config_text);
	/* The next run replaces the backup with the state before it. */
	backup_done = 0;
	CHECK(rewrite_file(config, REWRITE_CONFIG, &rules_back, NULL, 1,
	    &backup_done) == REWRITE_OK);
	CHECK_OWNED(read_all(bak),
	    "{\n  \"projects\": {\n    \"/L/third/repo\": {}\n  }\n}\n");
	CHECK_OWNED(read_all(config),
	    "{\n  \"projects\": {\n    \"/L/new/repo\": {}\n  }\n}\n");

	write_file(dir, "bad.json", "{\"projects\":{\"/L/old/repo\":{}}");
	bad = xjoin(dir, "bad.json");
	bad_bak = xjoin(dir, "bad.json.bak");
	backup_done = 0;
	CHECK(rewrite_file(bad, REWRITE_CONFIG, &test_rules, &plan, 1,
	    &backup_done) == REWRITE_INVALID);
	CHECK(plan.count == 0 && backup_done == 0);
	CHECK_OWNED(read_all(bad), "{\"projects\":{\"/L/old/repo\":{}}");
	CHECK(access(bad_bak, F_OK) != 0);
	missing = xjoin(dir, "missing.json");
	CHECK(rewrite_file(missing, REWRITE_CONFIG, &test_rules, &plan, 1,
	    &backup_done) == REWRITE_OK);
	CHECK(access(missing, F_OK) != 0);
	free(missing);

	/* A symlinked .claude.json stays a symlink; its target changes. */
	write_file(dir, "real.json", "{\"projects\":{\"/L/old/repo\":{}}}");
	real = xjoin(dir, "real.json");
	link = xjoin(dir, "link.json");
	CHECK(symlink("real.json", link) == 0);
	backup_done = 1;
	CHECK(rewrite_file(link, REWRITE_CONFIG, &test_rules, NULL, 1,
	    &backup_done) == REWRITE_OK);
	CHECK(lstat(link, &st) == 0 && S_ISLNK(st.st_mode));
	CHECK_OWNED(read_all(real), "{\"projects\":{\"/L/new/repo\":{}}}");

	CHECK(leftovers(dir) == 0);
	free(dir);
	free(file);
	free(other);
	free(index);
	free(config);
	free(bak);
	free(bad);
	free(bad_bak);
	free(real);
	free(link);
}

/* A line of n bytes of padding, so files can cross SESSION_CHUNK. */
static char *padding_line(size_t n)
{
	char *pad;

	pad = repeat("{\"type\":\"user\",\"text\":\"", 'x', n, "\"}\n");
	return pad;
}

static void test_relocated(const char *projects)
{
	char *dir, *pad, *text, *file;
	size_t n;

	dir = make_dir(projects, "-r-new");

	/* /cd moved the file here: the tail record wins over the head cwd. */
	write_file(dir, "a.jsonl", "{\"type\":\"mode\"}\n"
	    "{\"type\":\"user\",\"cwd\":\"/r/old\"}\n"
	    "{\"type\":\"relocated\",\"sessionId\":\"a\",\"relocatedCwd\":\"/r/mid\"}\n"
	    "{\"type\":\"user\",\"cwd\":\"/r/new\"}\n"
	    "{\"type\":\"relocated\",\"sessionId\":\"a\",\"relocatedCwd\":\"\\/r\\/new\"}\n"
	    "{\"type\":\"last-prompt\",\"lastPrompt\":\"x\"}");
	file = xjoin(dir, "a.jsonl");
	CHECK_OWNED(session_file_cwd(file), "/r/new");
	free(file);

	/* Only a top-level "type":"relocated" counts. */
	write_file(dir, "b.jsonl", "{\"type\":\"user\",\"cwd\":\"/r/b\"}\n"
	    "{\"type\":\"user\",\"message\":{\"type\":\"relocated\","
	    "\"relocatedCwd\":\"/no\"},\"relocatedCwd\":\"/no\"}\n"
	    "{\"type\":\"tag\",\"text\":\"\\\"relocated\\\"\"}\n");
	file = xjoin(dir, "b.jsonl");
	CHECK_OWNED(session_file_cwd(file), "/r/b");
	free(file);

	/* A record before the last SESSION_CHUNK bytes is not seen. */
	pad = padding_line(SESSION_CHUNK);
	n = strlen(pad);
	text = xmalloc(n + 200);
	snprintf(text, n + 200, "{\"cwd\":\"/r/c\"}\n"
	    "{\"type\":\"relocated\",\"relocatedCwd\":\"/r/early\"}\n%s", pad);
	write_file(dir, "c.jsonl", text);
	file = xjoin(dir, "c.jsonl");
	CHECK_OWNED(session_file_cwd(file), "/r/c");
	free(file);

	/* Nor is a cwd after the first SESSION_CHUNK bytes. */
	snprintf(text, n + 200, "%s{\"cwd\":\"/r/late\"}\n", pad);
	write_file(dir, "d.jsonl", text);
	file = xjoin(dir, "d.jsonl");
	CHECK_OWNED(session_file_cwd(file), NULL);
	free(file);

	/* A record at the end of a long file is found past a cut line. */
	snprintf(text, n + 200, "{\"cwd\":\"/r/e\"}\n%s"
	    "{\"type\":\"relocated\",\"relocatedCwd\":\"/r/end\"}\n", pad);
	write_file(dir, "e.jsonl", text);
	file = xjoin(dir, "e.jsonl");
	CHECK_OWNED(session_file_cwd(file), "/r/end");
	free(file);

	free(text);
	free(pad);
	free(dir);
}

static void test_session(void)
{
	char *projects, *dir, *sub, *agents, *link;

	projects = make_dir(getenv("CLAUDE_CONFIG_DIR"), "projects");

	/* The cwd that encodes to the directory name wins. */
	dir = make_dir(projects, "-r-repo");
	write_file(dir, "a.jsonl", "{\"type\":\"mode\"}\n"
	    "{\"type\":\"user\",\"cwd\":\"/r/repo/sub\"}\n");
	write_file(dir, "b.jsonl", "{\"type\":\"permission-mode\"}\n"
	    "{\"type\":\"user\",\"message\":{\"cwd\":\"/nested\"},"
	    "\"cwd\":\"\\/r\\/repo\"}\n");
	write_file(dir, "notes.txt", "{\"cwd\":\"/other\"}\n");
	CHECK_OWNED(session_dir_cwd(dir), "/r/repo");
	CHECK_OWNED(session_file_cwd("/nonexistent/x.jsonl"), NULL);
	free(dir);

	/* Without a match, the first file in name order. */
	dir = make_dir(projects, "-moved");
	write_file(dir, "b.jsonl", "{\"cwd\":\"/second\"}\n");
	write_file(dir, "a.jsonl", "{\"cwd\":\"/first\"}\n");
	CHECK_OWNED(session_dir_cwd(dir), "/first");
	free(dir);

	/* Only subagents: their cwd is the last resort. */
	dir = make_dir(projects, "-q");
	sub = make_dir(dir, "0000-uuid");
	agents = make_dir(sub, "subagents");
	write_file(agents, "agent-1.jsonl", "{\"cwd\":\"/q/sub\"}\n");
	write_file(sub, "custom-title.json", "{\"customTitle\":\"t\"}");
	CHECK_OWNED(session_dir_cwd(dir), "/q/sub");

	/* Symlinked directories are never followed. */
	free(dir);
	dir = make_dir(projects, "-linked");
	link = xjoin(dir, "link");
	CHECK(symlink(sub, link) == 0);
	CHECK_OWNED(session_dir_cwd(dir), NULL);
	free(link);
	free(agents);
	free(sub);
	free(dir);

	test_relocated(projects);

	/* No cwd anywhere, or no directory at all. */
	dir = make_dir(projects, "-empty");
	write_file(dir, "a.jsonl", "{\"type\":\"mode\"}\nnot json\n");
	free(make_dir(dir, "memory"));
	CHECK_OWNED(session_dir_cwd(dir), NULL);
	CHECK_OWNED(session_dir_cwd("/nonexistent"), NULL);
	free(dir);
	free(projects);
}

static void test_format(void)
{
	time_t t;

	setenv("LC_ALL", "en_US.UTF-8", 1);
	msg_init();
	CHECK_OWNED(format_count(1234567), "1234567");
	CHECK_OWNED(format_size(0), "0 B");
	CHECK_OWNED(format_size(999), "999 B");
	CHECK_OWNED(format_size(1000), "1.0 kB");
	CHECK_OWNED(format_size(1234567), "1.2 MB");
	CHECK_OWNED(format_size(999950), "1.0 MB");
	CHECK_OWNED(format_time(0), "\342\200\223");

	CHECK(parse_iso("2026-10-27T20:12:11.000Z", &t) == 0);
	CHECK(t == 1793131931);
	CHECK_OWNED(format_iso(t), "2026-10-27T20:12:11Z");
	CHECK(parse_iso("2026-10-27T21:42:11+01:30", &t) == 0);
	CHECK(t == 1793131931);
	CHECK(parse_iso("2026-10-27T20:12:11", &t) != 0);
	CHECK(parse_iso("2026-13-01T00:00:00Z", &t) != 0);
	CHECK(parse_iso("yesterday", &t) != 0);

	/* No escape sequence from a prompt reaches the terminal. */
	CHECK_OWNED(text_clean("a\tb\033[31m\302\205\377"), "a b [31m ?");
	CHECK_OWNED(text_clean("zażółć 🙂"), "zażółć 🙂");

	if (setlocale(LC_CTYPE, "en_US.UTF-8") != NULL) {
		CHECK(text_width("zażółć") == 6);
		CHECK(text_width("日本") == 4);
		CHECK_OWNED(text_fit("日本語", 5), "日本\342\200\246");
		CHECK_OWNED(text_fit("abc", 3), "abc");
		CHECK_OWNED(text_fit("abcd", 3), "ab\342\200\246");
		CHECK_OWNED(text_fit("abcd", 0), "");
		setlocale(LC_CTYPE, "C");
	}
}

static void test_state(void)
{
	const char *const none[] = { NULL };
	const char *mounts[2] = { NULL, NULL };
	char *dir, *locked, *path, *link, *volumes;

	dir = make_dir(work, "state");
	CHECK(path_state(NULL, none) == STATE_UNKNOWN);
	CHECK(path_state(dir, none) == STATE_ACTIVE);
	path = xjoin(dir, "gone/deeper");
	CHECK(path_state(path, none) == STATE_ORPHAN);
	free(path);

	/* A file where a directory should be is as good as nothing. */
	write_file(dir, "file", "");
	path = xjoin(dir, "file/repo");
	CHECK(path_state(path, none) == STATE_ORPHAN);
	free(path);

	/* A dangling symlink may point to a volume that is not mounted. */
	link = xjoin(dir, "dangling");
	CHECK(symlink("nowhere", link) == 0 || errno == EEXIST);
	path = xjoin(link, "repo");
	CHECK(path_state(path, none) == STATE_UNAVAILABLE);
	free(path);
	free(link);

	/* No access is not orphaned. */
	locked = make_dir(dir, "locked");
	free(make_dir(locked, "inner"));
	path = xjoin(locked, "inner/repo");
	CHECK(chmod(locked, 0) == 0);
	if (geteuid() != 0)
		CHECK(path_state(path, none) == STATE_UNAVAILABLE);
	CHECK(chmod(locked, 0755) == 0);
	CHECK(path_state(path, none) == STATE_ORPHAN);
	free(path);
	free(locked);

	/* Below a mount parent, a missing or bare volume is unavailable. */
	volumes = make_dir(dir, "Volumes");
	mounts[0] = volumes;
	path = xjoin(volumes, "Disk/repo");
	CHECK(path_state(path, mounts) == STATE_UNAVAILABLE);
	CHECK(path_state(path, none) == STATE_ORPHAN);
	free(path);
	free(make_dir(volumes, "Empty"));
	path = xjoin(volumes, "Empty/repo");
	CHECK(path_state(path, mounts) == STATE_UNAVAILABLE);
	free(path);
	link = xjoin(volumes, "Link");
	CHECK(symlink(dir, link) == 0 || errno == EEXIST);
	path = xjoin(link, "gone");
	CHECK(path_state(path, mounts) == STATE_ORPHAN);
	free(path);
	free(link);
	path = xjoin(dir, "gone");
	CHECK(path_state(path, mounts) == STATE_ORPHAN);
	free(path);
	free(volumes);

	CHECK_STR(state_name(STATE_ORPHAN), "orphan");
	CHECK_STR(state_name(STATE_UNAVAILABLE), "unavailable");
	free(dir);
}

static void test_session_info(void)
{
	struct session_info info;
	char *dir, *file, *fallback = NULL, *x250, *x200;

	dir = make_dir(work, "info");
	write_file(dir, "s1.jsonl",
	    "{\"type\":\"queue-operation\",\"timestamp\":\"2026-10-27T20:00:00Z\"}\n"
	    "{\"type\":\"user\",\"isMeta\":true,\"timestamp\":\"2026-10-27T20:00:01.000Z\","
	    "\"gitBranch\":\"main\",\"message\":{\"content\":\"meta\"}}\n"
	    "{\"type\":\"user\",\"message\":{\"content\":"
	    "\"<command-name>/clear</command-name><command-args></command-args>\"}}\n"
	    "{\"type\":\"user\",\"message\":{\"content\":"
	    "\"<local-command-stdout>x</local-command-stdout>\"}}\n"
	    "{\"type\":\"user\",\"message\":{\"content\":[{\"type\":\"tool_result\"}]}}\n"
	    "{\"type\":\"assistant\",\"message\":{\"content\":[{\"type\":\"tool_use\"}]}}\n"
	    "{\"type\":\"assistant\",\"message\":{\"content\":[{\"type\":\"text\",\"text\":\" \"}]}}\n"
	    "{\"type\":\"user\",\"message\":{\"content\":\"[Request interrupted by user]\"}}\n"
	    "{\"type\":\"user\",\"gitBranch\":\"feature\",\"message\":{\"content\":"
	    "[{\"text\":\"Fix\\nthe bug \",\"type\":\"text\"},{\"type\":\"image\"}]}}\n"
	    "{\"type\":\"assistant\",\"gitBranch\":\"\",\"message\":{\"content\":"
	    "[{\"type\":\"text\",\"text\":\"Done.\"}]}}\n"
	    "not json\n"
	    "{\"type\":\"user\",\"message\":{\"content\":\"later\"");
	file = xjoin(dir, "s1.jsonl");
	CHECK(session_info_read(file, &info) == 0);
	CHECK_STR(info.id, "s1");
	CHECK(info.messages == 5);
	CHECK(info.started == 1793131201);
	CHECK(info.modified != 0);
	CHECK_STR(info.branch, "feature");
	CHECK_STR(info.prompt, "Fix the bug");
	session_info_free(&info);
	free(file);

	/* A slash command without arguments only when nothing else follows. */
	write_file(dir, "s2.jsonl", "{\"type\":\"user\",\"message\":{\"content\":"
	    "\"<command-name>/clear</command-name>\"}}\n");
	file = xjoin(dir, "s2.jsonl");
	CHECK(session_info_read(file, &info) == 0);
	CHECK_STR(info.prompt, "/clear");
	CHECK(info.started == 0);
	CHECK(info.branch == NULL);
	CHECK(info.title == NULL);
	session_info_free(&info);
	free(file);

	/* The last given name wins; an empty one does not clear it. */
	write_file(dir, "s4.jsonl",
	    "{\"type\":\"ai-title\",\"aiTitle\":\"Fixing bugs\"}\n"
	    "{\"type\":\"custom-title\",\"customTitle\":\"stage 1\"}\n"
	    "{\"type\":\"custom-title\",\"customTitle\":\"stage 2\"}\n"
	    "{\"type\":\"custom-title\",\"customTitle\":\"\"}\n"
	    "{\"type\":\"ai-title\",\"aiTitle\":\"Later\"}\n");
	file = xjoin(dir, "s4.jsonl");
	CHECK(session_info_read(file, &info) == 0);
	CHECK_STR(info.title, "stage 2");
	session_info_free(&info);
	free(file);

	/* Without a name of its own, the one Claude gave it. */
	write_file(dir, "s5.jsonl",
	    "{\"type\":\"ai-title\",\"aiTitle\":\"Fixing bugs\"}\n"
	    "{\"type\":\"ai-title\",\"aiTitle\":\"Fixing the parser\"}\n");
	file = xjoin(dir, "s5.jsonl");
	CHECK(session_info_read(file, &info) == 0);
	CHECK_STR(info.title, "Fixing the parser");
	session_info_free(&info);
	free(file);

	write_file(dir, "s3.jsonl", "");
	file = xjoin(dir, "s3.jsonl");
	CHECK(session_info_read(file, &info) == 0);
	CHECK(info.messages == 0);
	CHECK(info.prompt == NULL);
	session_info_free(&info);
	free(file);
	CHECK(session_info_read("/nonexistent/x.jsonl", &info) != 0);

	CHECK_OWNED(session_prompt("<command-name>/review</command-name>"
	    "<command-args> PR 5 </command-args>", &fallback), "/review PR 5");
	CHECK_OWNED(session_prompt("<bash-input>ls -l</bash-input>", &fallback),
	    "! ls -l");
	CHECK_OWNED(session_prompt("  <system-reminder>x", &fallback), NULL);
	CHECK_OWNED(session_prompt("see <tag>", &fallback), "see <tag>");
	CHECK_OWNED(session_prompt(" \n ", &fallback), NULL);
	CHECK(fallback == NULL);
	x250 = repeat("", 'x', 250, "");
	x200 = repeat("", 'x', 200, "\342\200\246");
	CHECK_OWNED(session_prompt(x250, &fallback), x200);
	free(x250);
	free(x200);
	free(dir);
}

static void test_version(void)
{
	struct timespec times[2];
	char *base, *a, *b, *sub, *file, *v;

	CHECK(session_version_compare("2.1.314", "2.1.314") == 0);
	CHECK(session_version_compare("2.1.316", "2.1.314") > 0);
	CHECK(session_version_compare("2.1.9", "2.1.10") < 0);
	CHECK(session_version_compare("2.2.0", "2.1.999") > 0);
	CHECK(session_version_compare("2.1", "2.1.0") < 0);
	CHECK(session_version_compare("2.1.0-beta", "2.1.0") > 0);

	base = make_dir(work, "version");
	CHECK(session_claude_version(base) == NULL);
	a = make_dir(base, "-a");
	b = make_dir(base, "-b");
	write_file(a, "old.jsonl", "{\"type\":\"user\",\"version\":\"2.1.200\"}\n");
	write_file(b, "new.jsonl",
	    "{\"type\":\"user\",\"version\":\"2.1.300\"}\n"
	    "{\"type\":\"user\",\"message\":{\"version\":\"9\"}}\n"
	    "{\"type\":\"user\",\"version\":\"2.1.316\"}\n"
	    "{\"type\":\"custom-title\",\"customTitle\":\"x\"}\n");
	/* Files below a session directory do not count, however new. */
	sub = make_dir(b, "uuid");
	write_file(sub, "agent.jsonl", "{\"type\":\"user\",\"version\":\"7\"}\n");
	times[0].tv_sec = times[1].tv_sec = 1793131200;
	times[0].tv_nsec = times[1].tv_nsec = 0;
	file = xjoin(a, "old.jsonl");
	CHECK(utimensat(AT_FDCWD, file, times, 0) == 0);
	free(file);
	CHECK_OWNED(session_claude_version(base), "2.1.316");

	/* The newest file decides, even when it has no version. */
	times[0].tv_sec = times[1].tv_sec = 1893456000;
	write_file(a, "newer.jsonl", "{\"type\":\"user\"}\n");
	file = xjoin(a, "newer.jsonl");
	CHECK(utimensat(AT_FDCWD, file, times, 0) == 0);
	free(file);
	CHECK(session_claude_version(base) == NULL);

	/* What is not a version is not shown. */
	write_file(a, "newer.jsonl",
	    "{\"type\":\"user\",\"version\":\"\\u001b[2J\"}\n");
	file = xjoin(a, "newer.jsonl");
	CHECK(utimensat(AT_FDCWD, file, times, 0) == 0);
	free(file);
	CHECK(session_claude_version(base) == NULL);

	CHECK(format_version_warning(NULL) == NULL);
	CHECK(format_version_warning(SESSION_TESTED_VERSION) == NULL);
	v = format_version_warning("99.0.0");
	CHECK(v != NULL && strstr(v, "new version, 99.0.0") != NULL &&
	    strstr(v, SESSION_TESTED_VERSION) != NULL);
	free(v);
	v = format_version_warning("1.0.0");
	CHECK(v != NULL && strstr(v, "is version 1.0.0") != NULL);
	free(v);
	free(sub);
	free(a);
	free(b);
	free(base);
}

static void test_inventory(void)
{
	struct inventory inv;
	struct timespec times[2];
	char *base, *projects, *repo, *gone, *mem, *dir, *sub, *link, *name;
	char *text;
	size_t found[8], n, size, cap;

	base = make_dir(work, "inv");
	projects = make_dir(base, "projects");
	repo = make_dir(base, "repo");
	gone = xjoin(base, "gone");
	mem = xjoin(base, "mem");

	name = path_encode(repo);
	dir = make_dir(projects, name);
	free(name);
	cap = strlen(base) + 32;
	text = xmalloc(cap);
	snprintf(text, cap, "{\"cwd\":\"%s\"}\n", repo);
	write_file(dir, "a.jsonl", text);
	size = strlen(text) + strlen("{\"type\":\"mode\"}\n") + 5;
	write_file(dir, "b.jsonl", "{\"type\":\"mode\"}\n");
	sub = make_dir(dir, "memory");
	write_file(sub, "MEMORY.md", "12345");
	/* The newest file sets the last change; the rest is older. */
	times[0].tv_sec = times[1].tv_sec = 1000000000;
	times[0].tv_nsec = times[1].tv_nsec = 0;
	link = xjoin(dir, "a.jsonl");
	CHECK(utimensat(AT_FDCWD, link, times, 0) == 0);
	free(link);
	link = xjoin(dir, "b.jsonl");
	CHECK(utimensat(AT_FDCWD, link, times, 0) == 0);
	free(link);
	times[0].tv_sec = times[1].tv_sec = 1500000000;
	link = xjoin(sub, "MEMORY.md");
	CHECK(utimensat(AT_FDCWD, link, times, 0) == 0);
	free(link);
	link = xjoin(sub, "elsewhere");
	CHECK(symlink("/", link) == 0 || errno == EEXIST);
	free(link);
	free(sub);
	free(dir);

	dir = make_dir(projects, "-inv-gone");
	snprintf(text, cap, "{\"cwd\":\"%s\"}\n", gone);
	write_file(dir, "c.jsonl", text);
	free(dir);

	name = path_encode(mem);
	dir = make_dir(projects, name);
	free(name);
	free(make_dir(dir, "memory"));
	free(dir);

	write_file(projects, "stray.txt", "x");
	link = xjoin(projects, "-linked");
	CHECK(symlink(repo, link) == 0 || errno == EEXIST);
	free(link);

	CHECK(inventory_scan(projects, &inv) == 0);
	CHECK(inv.count == 3);
	if (inv.count == 3) {
		CHECK_STR(inv.dirs[0].project, gone);
		CHECK(inv.dirs[0].state == STATE_ORPHAN);
		CHECK_STR(inv.dirs[1].project, repo);
		CHECK(inv.dirs[1].state == STATE_ACTIVE);
		CHECK(inv.dirs[1].sessions == 2);
		CHECK(inv.dirs[1].size == size);
		CHECK(inv.dirs[1].modified == 1500000000);
		CHECK(inv.dirs[2].project == NULL);
		CHECK(inv.dirs[2].state == STATE_UNKNOWN);
		CHECK(inv.dirs[2].sessions == 0);
		CHECK(inv.dirs[2].size == 0);

		CHECK(inventory_match(&inv, "-inv-gone", found) == 1);
		CHECK(found[0] == 0);
		n = inventory_match(&inv, repo, found);
		CHECK(n == 1 && found[0] == 1);
		/* Relative to the work directory, the tests' cwd. */
		n = inventory_match(&inv, "inv/repo", found);
		CHECK(n == 1 && found[0] == 1);
		n = inventory_match(&inv, "inv/mem", found);
		CHECK(n == 1 && found[0] == 2);
		CHECK(inventory_match(&inv, "inv/repo/sub", found) == 0);
		CHECK(inventory_match(&inv, "-nothing", found) == 0);
	}
	inventory_free(&inv);

	link = xjoin(base, "none");
	CHECK(inventory_scan(link, &inv) == 0);
	CHECK(inv.count == 0);
	free(link);
	free(text);
	free(mem);
	free(gone);
	free(repo);
	free(projects);
	free(base);
}

static const struct cli_option test_options[] = {
	{ 'n', "dry-run", 0, 0 },
	{ 'y', "yes", 0, 1 },
	{ 'o', "out", 1, 2 },
	{ 0, NULL, 0, 0 }
};

static int parse(struct cli_parsed *p, char **argv)
{
	int argc;

	for (argc = 0; argv[argc] != NULL; argc++)
		;
	return cli_parse(argc, argv, test_options, p);
}

static void test_cli(void)
{
	struct cli_parsed p;
	char *a1[] = { "mv", "-ny", "a", "--dry-run", "--", "-b", "-", "c", NULL };
	char *a2[] = { "-ofile", "x", NULL };
	char *a3[] = { "-no", "file", NULL };
	char *a4[] = { "--out=f=g", NULL };
	char *a5[] = { "--out", "f", NULL };
	char *a6[] = { "--out", NULL };
	char *a7[] = { "--yes=1", NULL };
	char *a8[] = { "-nx", NULL };
	char *a9[] = { "--nope=3", NULL };
	char *a10[] = { "--dry", NULL };
	char *a11[] = { "-o", NULL };

	CHECK(parse(&p, a1) == 0);
	CHECK(p.flags == 3);
	CHECK(p.operand_count == 5);
	CHECK_STR(p.operands[0], "mv");
	CHECK_STR(p.operands[1], "a");
	CHECK_STR(p.operands[2], "-b");
	CHECK_STR(p.operands[3], "-");
	CHECK_STR(p.operands[4], "c");
	CHECK(p.operands[5] == NULL);
	cli_free(&p);

	CHECK(parse(&p, a2) == 0);
	CHECK_STR(p.args[2], "file");
	CHECK(p.operand_count == 1);
	cli_free(&p);

	CHECK(parse(&p, a3) == 0);
	CHECK(p.flags == 5);
	CHECK_STR(p.args[2], "file");
	CHECK(p.operand_count == 0);
	cli_free(&p);

	CHECK(parse(&p, a4) == 0);
	CHECK_STR(p.args[2], "f=g");
	cli_free(&p);

	CHECK(parse(&p, a5) == 0);
	CHECK_STR(p.args[2], "f");
	cli_free(&p);

	CHECK(parse(&p, a6) != 0);
	CHECK(p.error == CLI_NEEDS_ARG);
	CHECK_STR(p.error_option, "--out");
	cli_free(&p);

	CHECK(parse(&p, a7) != 0);
	CHECK(p.error == CLI_NO_ARG);
	CHECK_STR(p.error_option, "--yes");
	cli_free(&p);

	CHECK(parse(&p, a8) != 0);
	CHECK(p.error == CLI_UNKNOWN);
	CHECK_STR(p.error_option, "-x");
	cli_free(&p);

	CHECK(parse(&p, a9) != 0);
	CHECK_STR(p.error_option, "--nope");
	cli_free(&p);

	/* Abbreviated long options are not accepted. */
	CHECK(parse(&p, a10) != 0);
	CHECK(p.error == CLI_UNKNOWN);
	cli_free(&p);

	CHECK(parse(&p, a11) != 0);
	CHECK(p.error == CLI_NEEDS_ARG);
	CHECK_STR(p.error_option, "-o");
	cli_free(&p);
}

/* config_take_project on text; *value gets the raw entry (NULL for none). */
static char *take(const char *text, const char *key, char **value)
{
	char *out;
	size_t len;

	if (config_take_project(text, strlen(text), key, value, &out, &len) !=
	    REWRITE_OK)
		return xstrdup("invalid");
	return out;
}

static char *put(const char *text, const char *key, const char *value)
{
	char *out;
	size_t len;
	int r;

	r = config_put_project(text, strlen(text), key, value, &out, &len);
	if (r == REWRITE_EXISTS)
		return xstrdup("exists");
	if (r != REWRITE_OK)
		return xstrdup("invalid");
	return out;
}

static const char pretty[] =
    "{\n"
    "  \"numStartups\": 3,\n"
    "  \"projects\": {\n"
    "    \"/a\": {\n"
    "      \"allowedTools\": []\n"
    "    },\n"
    "    \"/b\": {\n"
    "      \"t\": 1\n"
    "    },\n"
    "    \"/c\": {}\n"
    "  },\n"
    "  \"z\": 1\n"
    "}\n";

static void test_trash_config(void)
{
	char *value, *out;

	/* The last member takes its separator along; back it comes the same. */
	out = take(pretty, "/c", &value);
	CHECK_STR(value, "{}");
	CHECK(out != NULL && strstr(out, "\"t\": 1\n    }\n  },") != NULL);
	CHECK_OWNED(put(out, "/c", value), pretty);
	free(out);
	free(value);

	/* A member in the middle; it comes back as the last one. */
	out = take(pretty, "/b", &value);
	CHECK_STR(value, "{\n      \"t\": 1\n    }");
	CHECK(out != NULL && strstr(out, "[]\n    },\n    \"/c\": {}\n") != NULL);
	CHECK_OWNED(put(out, "/b", value),
	    "{\n"
	    "  \"numStartups\": 3,\n"
	    "  \"projects\": {\n"
	    "    \"/a\": {\n"
	    "      \"allowedTools\": []\n"
	    "    },\n"
	    "    \"/c\": {},\n"
	    "    \"/b\": {\n"
	    "      \"t\": 1\n"
	    "    }\n"
	    "  },\n"
	    "  \"z\": 1\n"
	    "}\n");
	free(out);
	free(value);

	/* The first member takes the separator after it. */
	out = take(pretty, "/a", &value);
	CHECK(out != NULL && strstr(out, "\"projects\": {\n    \"/b\"") != NULL);
	free(out);
	free(value);

	/* The only member leaves {}, as Claude Code writes it, and comes back. */
	out = take("{\n  \"projects\": {\n    \"/a\": {\n      \"t\": 1\n    }\n"
	    "  }\n}\n", "/a", &value);
	CHECK_STR(out, "{\n  \"projects\": {}\n}\n");
	CHECK_OWNED(put(out, "/a", value),
	    "{\n  \"projects\": {\n    \"/a\": {\n      \"t\": 1\n    }\n"
	    "  }\n}\n");
	free(out);
	free(value);

	/* Two equal keys: both go, the last one counts (JSON.parse). */
	CHECK_OWNED(take("{\"projects\":{\"/a\":1,\"/x\":0,\"/a\":2}}", "/a",
	    &value), "{\"projects\":{\"/x\":0}}");
	CHECK_OWNED(value, "2");

	/* Only the top-level projects; no entry, no change. */
	CHECK_OWNED(take("{\"o\":{\"projects\":{\"/a\":1}}}", "/a", &value),
	    NULL);
	CHECK(value == NULL);
	CHECK_OWNED(take("{\"projects\":{\"/a\\u0022\":1}}", "/a\"", &value),
	    "{\"projects\":{}}");
	CHECK_OWNED(value, "1");
	CHECK_OWNED(take("{\"projects\":{", "/a", &value), "invalid");
	CHECK(value == NULL);

	CHECK_OWNED(put("{\"projects\":{\"/a\":1}}", "/b\"", "2"),
	    "{\"projects\":{\"/a\":1,\"/b\\\"\":2}}");
	CHECK_OWNED(put("{\"projects\":{\"/a\":1}}", "/a", "2"), "exists");
	CHECK_OWNED(put("{\"projects\":{}}", "/a", "1"),
	    "{\"projects\":{\"/a\":1}}");
	CHECK_OWNED(put("{\n  \"x\": 1\n}\n", "/a", "{}"),
	    "{\n  \"x\": 1,\n  \"projects\": {\n    \"/a\": {}\n  }\n}\n");
	CHECK_OWNED(put("{}", "/a", "1"), "{\"projects\":{\"/a\":1}}");
	CHECK_OWNED(put("{\"projects\":[]}", "/a", "1"), "invalid");
	CHECK_OWNED(put("[]", "/a", "1"), "invalid");
}

static int answer(const char *input)
{
	FILE *in, *out;
	int r;

	in = tmpfile();
	out = tmpfile();
	if (in == NULL || out == NULL) {
		printf("cannot create a temporary file\n");
		exit(1);
	}
	fputs(input, in);
	rewind(in);
	r = cli_confirm(in, out, "Sure?");
	fclose(in);
	fclose(out);
	return r;
}

static void test_trash_files(void)
{
	struct stat st;
	char *dir, *keep, *link;

	CHECK_OWNED(trash_entry_name(1761603000, "-Users-m-repo", 1),
	    "20251027T221000Z-Users-m-repo");
	CHECK_OWNED(trash_entry_name(1761603000, "-Users-m-repo", 2),
	    "20251027T221000Z-Users-m-repo-2");
	CHECK_OWNED(trash_entry_name(0, "name", 1), "19700101T000000Z-name");

	dir = xjoin(work, "trash/a/b/c");
	CHECK(dir_make(dir, 0700) == 0);
	CHECK(stat(dir, &st) == 0 && S_ISDIR(st.st_mode));
	CHECK(dir_make(dir, 0700) == 0);
	free(dir);

	/* A symlink inside goes, what it points to stays. */
	keep = make_dir(work, "trash-keep");
	write_file(keep, "file", "x");
	dir = xjoin(work, "trash/a");
	link = xjoin(work, "trash/a/b/link");
	CHECK(symlink(keep, link) == 0);
	write_file(dir, "f", "y");
	CHECK(tree_remove(dir) == 0);
	CHECK(lstat(dir, &st) != 0 && errno == ENOENT);
	CHECK(stat(keep, &st) == 0);
	free(link);
	link = xjoin(keep, "file");
	CHECK(stat(link, &st) == 0);
	free(link);
	free(keep);
	free(dir);

	setenv("LC_ALL", "en_US.UTF-8", 1);
	msg_init();
	CHECK(answer("y\n") == 1);
	CHECK(answer("  YES  \n") == 1);
	CHECK(answer("\n") == 0);
	CHECK(answer("") == 0);
	CHECK(answer("n\n") == 0);
	CHECK(answer("yy\n") == 0);
	CHECK(answer("t\n") == 0);
	setenv("LC_ALL", "pl_PL.UTF-8", 1);
	msg_init();
	CHECK(answer("t\n") == 1);
	CHECK(answer("Tak\n") == 1);
	CHECK(answer("y\n") == 0);
	unsetenv("LC_ALL");
	msg_init();
}

static int has_note(const struct move_ctx *ctx, const char *key)
{
	size_t i;

	for (i = 0; i < ctx->note_count; i++)
		if (strcmp(ctx->notes[i].key, key) == 0)
			return 1;
	return 0;
}

/* The core of -r and -u on a session directory of an orphaned project. */
static void test_trash_flow(void)
{
	struct session_dir_info info;
	struct trash_entry *entries;
	struct move_ctx ctx;
	struct stat st;
	char *projects, *dir, *trash, *file, *data, *name;
	size_t count, len;
	static const char config[] =
	    "{\"projects\":{\"/gone/repo\":{\"t\":1},\"/x\":{}}}";

	move_init(&ctx, 1);
	projects = make_dir(ctx.config_dir, "projects");
	dir = make_dir(projects, "-gone-repo");
	write_file(dir, "s.jsonl", "{\"type\":\"user\",\"cwd\":\"/gone/repo\"}\n");
	write_file(ctx.config_dir, ".claude.json", config);
	inventory_read_dir(dir, &info);
	CHECK(info.state == STATE_ORPHAN);

	/* -n plans only. */
	ctx.apply = 0;
	trash_remove(&ctx, &info);
	CHECK(has_note(&ctx, "remove.config"));
	CHECK(stat(dir, &st) == 0);
	move_clear(&ctx);

	/* .claude.json cannot change: the directory goes back, the entry too. */
	ctx.apply = 1;
	CHECK(chmod(ctx.config_dir, 0500) == 0);
	trash_remove(&ctx, &info);
	CHECK(chmod(ctx.config_dir, 0700) == 0);
	CHECK(has_note(&ctx, "error.remove.config"));
	CHECK(stat(dir, &st) == 0 && S_ISDIR(st.st_mode));
	trash = trash_path(&ctx);
	CHECK(trash_list(trash, &entries, &count) == 0 && count == 0);
	trash_list_free(entries, count);
	move_clear(&ctx);
	ctx.failed = 0;

	trash_remove(&ctx, &info);
	CHECK(!ctx.failed);
	CHECK(lstat(dir, &st) != 0 && errno == ENOENT);
	file = xjoin(ctx.config_dir, ".claude.json");
	CHECK(file_read(file, &data, &len) == 0);
	CHECK_STR(data, "{\"projects\":{\"/x\":{}}}");
	free(data);
	CHECK(trash_list(trash, &entries, &count) == 0 && count == 1);
	name = count == 1 ? xstrdup(entries[0].name) : xstrdup("");
	if (count == 1) {
		CHECK_STR(entries[0].dir, "-gone-repo");
		CHECK_STR(entries[0].origin, dir);
		CHECK_STR(entries[0].project, "/gone/repo");
		CHECK_STR(entries[0].config_file, file);
		CHECK_STR(entries[0].projects_key, "/gone/repo");
		CHECK_STR(entries[0].projects_value, "{\"t\":1}");
		CHECK(entries[0].removed > 0);
		CHECK(entries[0].size > 0);
	}
	trash_list_free(entries, count);
	move_clear(&ctx);

	trash_restore(&ctx, name);
	CHECK(!ctx.failed);
	CHECK(stat(dir, &st) == 0 && S_ISDIR(st.st_mode));
	CHECK(file_read(file, &data, &len) == 0);
	CHECK_STR(data, "{\"projects\":{\"/x\":{},\"/gone/repo\":{\"t\":1}}}");
	free(data);
	CHECK(trash_list(trash, &entries, &count) == 0 && count == 0);
	trash_list_free(entries, count);
	move_clear(&ctx);

	trash_restore(&ctx, "../etc");
	CHECK(has_note(&ctx, "error.trash.none"));
	move_clear(&ctx);

	free(info.name);
	free(info.path);
	free(info.project);
	free(name);
	free(file);
	free(trash);
	free(dir);
	free(projects);
	move_free(&ctx);
}

static void field_press(struct field *f, enum key_code code, const char *text)
{
	struct key k;

	memset(&k, 0, sizeof k);
	k.code = code;
	snprintf(k.text, sizeof k.text, "%s", text);
	field_key(f, &k);
}

/* The path field: line editing, the home directory, Tab completion. */
static void test_field(void)
{
	struct field f;
	char **list, *dir, *text, *common;
	size_t n;

	field_set(&f, "/a/b");
	CHECK(f.len == 4 && f.pos == 4);
	field_press(&f, KEY_CHAR, "\303\263");
	CHECK_STR(f.text, "/a/b\303\263");
	field_press(&f, KEY_LEFT, "");
	CHECK(f.pos == 4);
	field_press(&f, KEY_CHAR, "x");
	CHECK_STR(f.text, "/a/bx\303\263");
	field_press(&f, KEY_BACKSPACE, "");
	field_press(&f, KEY_DELETE, "");
	CHECK_STR(f.text, "/a/b");
	field_press(&f, KEY_HOME, "");
	CHECK(f.pos == 0);
	field_press(&f, KEY_CTRL, "e");
	CHECK(f.pos == 4);
	/* Ctrl-W takes one directory at a time. */
	field_press(&f, KEY_CTRL, "w");
	CHECK_STR(f.text, "/a/");
	field_press(&f, KEY_CTRL, "w");
	CHECK_STR(f.text, "/");
	field_set(&f, "abc");
	field_press(&f, KEY_LEFT, "");
	field_press(&f, KEY_CTRL, "k");
	CHECK_STR(f.text, "ab");
	field_press(&f, KEY_CTRL, "u");
	CHECK(f.len == 0 && f.pos == 0);
	CHECK(!field_key(&f, &(struct key){ .code = KEY_UP }));
	/* A text too long is cut on a character boundary. */
	text = repeat("", 'a', FIELD_MAX - 2, "\303\263");
	field_set(&f, text);
	CHECK(f.len == FIELD_MAX - 2);
	free(text);

	CHECK_OWNED(field_path("~/x", "/h"), "/h/x");
	CHECK_OWNED(field_path("~", "/h"), "/h");
	CHECK_OWNED(field_path("~x", "/h"), "~x");
	CHECK_OWNED(field_path("~/x", NULL), "~/x");

	dir = make_dir(work, "complete");
	free(make_dir(dir, "alpha"));
	free(make_dir(dir, "alpine"));
	free(make_dir(dir, "beta"));
	free(make_dir(dir, ".hidden"));
	write_file(dir, "alfile", "");
	text = xjoin(dir, "al");
	list = field_complete(text, NULL, &n);
	CHECK(n == 2);
	if (n == 2) {
		CHECK(strstr(list[0], "/complete/alpha/") != NULL);
		CHECK(strstr(list[1], "/complete/alpine/") != NULL);
		common = field_common(list, n);
		CHECK(strlen(common) > 3 &&
		    strcmp(common + strlen(common) - 4, "/alp") == 0);
		free(common);
	}
	field_list_free(list, n);
	free(text);
	list = field_complete("complete/b", NULL, &n);
	CHECK(n == 1 && strcmp(list[0], "complete/beta/") == 0);
	field_list_free(list, n);
	list = field_complete("complete/.", NULL, &n);
	CHECK(n == 1 && strcmp(list[0], "complete/.hidden/") == 0);
	field_list_free(list, n);
	list = field_complete("complete/z", NULL, &n);
	CHECK(n == 0);
	field_list_free(list, n);
	list = field_complete("~/", dir, &n);
	CHECK(n == 3 && strcmp(list[2], "~/beta/") == 0);
	field_list_free(list, n);
	list = field_complete("~", dir, &n);
	CHECK(n == 1 && strcmp(list[0], "~/") == 0);
	field_list_free(list, n);
	CHECK_OWNED(field_common(NULL, 0), "");

	if (setlocale(LC_CTYPE, "en_US.UTF-8") != NULL) {
		field_set(&f, "\346\227\245\346\234\254x");
		f.pos = 3;
		CHECK(field_cursor_width(&f) == 2);
		/* The common start never ends inside a character. */
		list = xmalloc(2 * sizeof *list);
		list[0] = xstrdup("a\303\263");
		list[1] = xstrdup("a\303\272");
		CHECK_OWNED(field_common(list, 2), "a");
		field_list_free(list, 2);
		setlocale(LC_CTYPE, "C");
	}
	free(dir);
}

/* githubRepoPaths: listing, dropping byte for byte, the states, -P. */
static void test_github(void)
{
	static const char text[] =
	    "{\"githubRepoPaths\": {\n"
	    "  \"o/a\": [\n"
	    "    \"/1\",\n"
	    "    \"/2\",\n"
	    "    3\n"
	    "  ],\n"
	    "  \"o/b\": [\"/3\"]\n"
	    "}, \"x\": {\"githubRepoPaths\": {\"o/c\": [\"/9\"]}}}";
	struct change_list plan = { NULL, 0, 0 };
	struct github_path *paths;
	struct github_entry *entries;
	struct inventory inv;
	struct session_dir_info info;
	struct move_ctx ctx;
	char *base, *live, *gone, *link, *unavailable, *json, *data, *bak;
	char *out, **list, *place, *other;
	char *repos[1];
	size_t n, len, cap;

	CHECK(config_github_paths(text, sizeof text - 1, &paths, &n) ==
	    REWRITE_OK);
	CHECK(n == 4);
	if (n == 4) {
		CHECK_STR(paths[0].repo, "o/a");
		CHECK_STR(paths[1].path, "/2");
		CHECK(paths[2].path == NULL);
		CHECK_STR(paths[3].repo, "o/b");
	}
	github_paths_free(paths, n);
	CHECK(config_drop_github(text, sizeof text - 1, "c", "\1\0\0\1", &plan,
	    &out, &len) == REWRITE_OK);
	CHECK_STR(out,
	    "{\"githubRepoPaths\": {\n"
	    "  \"o/a\": [\n"
	    "    \"/2\",\n"
	    "    3\n"
	    "  ],\n"
	    "  \"o/b\": []\n"
	    "}, \"x\": {\"githubRepoPaths\": {\"o/c\": [\"/9\"]}}}");
	free(out);
	CHECK(plan.count == 2);
	CHECK_CHANGE(&plan, 0, CHANGE_DROP, "githubRepoPaths[\"o/a\"][0]", "/1",
	    NULL);
	CHECK_CHANGE(&plan, 1, CHANGE_DROP, "githubRepoPaths[\"o/b\"][0]", "/3",
	    NULL);
	change_list_free(&plan);
	CHECK(config_github_paths("{", 1, &paths, &n) == REWRITE_INVALID);

	base = make_dir(work, "github");
	live = make_dir(base, "live");
	gone = xjoin(base, "gone");
	link = xjoin(base, "link");
	CHECK(symlink("nowhere", link) == 0 || errno == EEXIST);
	unavailable = xjoin(link, "repo");
	cap = 4 * strlen(base) + 256;
	json = xmalloc(cap);
	snprintf(json, cap, "{\"githubRepoPaths\":{\"o/r\":[\"%s\",\"%s\","
	    "\"%s\"],\"o/s\":[\"%s/two\"]}}", live, gone, unavailable, gone);
	move_init(&ctx, 0);
	write_file(ctx.config_dir, ".claude.json", json);
	CHECK(github_scan(ctx.config_file, &entries, &n) == 0 && n == 4);
	CHECK(github_dead(entries, n) == 2);
	CHECK(github_has_repo(entries, n, "O/R"));
	CHECK(!github_has_repo(entries, n, "o/x"));
	github_entries_free(entries, n);

	/* A plan only: the unavailable path is said to stay. */
	CHECK(github_prune(&ctx, NULL, 0) == 2);
	CHECK(has_note(&ctx, "prune.entry"));
	CHECK(has_note(&ctx, "prune.unavailable"));
	CHECK(ctx.plan.count == 2);
	CHECK(file_read(ctx.config_file, &data, &len) == 0);
	CHECK_STR(data, json);
	free(data);
	move_clear(&ctx);
	repos[0] = "O/S";
	CHECK(github_prune(&ctx, repos, 1) == 1);
	move_clear(&ctx);

	ctx.apply = 1;
	repos[0] = "o/r";
	CHECK(github_prune(&ctx, repos, 1) == 1);
	CHECK(!ctx.failed);
	CHECK(file_read(ctx.config_file, &data, &len) == 0);
	out = xmalloc(cap);
	snprintf(out, cap, "{\"githubRepoPaths\":{\"o/r\":[\"%s\",\"%s\"],"
	    "\"o/s\":[\"%s/two\"]}}", live, unavailable, gone);
	CHECK_STR(data, out);
	free(out);
	free(data);
	bak = xmalloc(strlen(ctx.config_file) + 5);
	sprintf(bak, "%s.bak", ctx.config_file);
	CHECK(file_read(bak, &data, &len) == 0);
	CHECK_STR(data, json);
	free(data);
	free(bak);
	move_clear(&ctx);

	/* Fix candidates: the same repository first, then a sibling's name. */
	snprintf(json, cap, "{\"githubRepoPaths\":{\"o/p\":[\"%s\",\"%s\"]}}",
	    gone, live);
	write_file(ctx.config_dir, ".claude.json", json);
	place = make_dir(base, "place");
	other = make_dir(place, "other");
	free(make_dir(place, "gone"));
	memset(&info, 0, sizeof info);
	info.state = STATE_ACTIVE;
	info.project = other;
	inv.dirs = &info;
	inv.count = 1;
	list = fix_candidates(gone, &inv, ctx.config_file, &n);
	CHECK(n == 2);
	if (n == 2) {
		CHECK_STR(list[0], live);
		CHECK(strcmp(list[1], gone) != 0 &&
		    strstr(list[1], "/place/gone") != NULL);
	}
	fix_candidates_free(list, n);
	info.state = STATE_ORPHAN;
	list = fix_candidates(gone, &inv, "/nonexistent/.claude.json", &n);
	CHECK(n == 0);
	fix_candidates_free(list, n);

	unlink(ctx.config_file);
	move_free(&ctx);
	free(other);
	free(place);
	free(json);
	free(unavailable);
	free(link);
	free(gone);
	free(live);
	free(base);
}

/* What the CLI prints and the TUI previews: headings, indents, the plan. */
static void test_report(void)
{
	struct path_pair pair = { "/a/repo", "/b/repo" };
	struct rewrite_rules rules = { &pair, 1, NULL, NULL };
	struct report r = { NULL, 0, 0 };
	struct move_ctx ctx;
	char *out, *file;
	size_t len;

	setenv("LC_ALL", "en", 1);
	msg_init();
	move_init(&ctx, 0);
	move_note(&ctx, NOTE_INFO, "move.repo", "/a/repo", "/b/repo", 0);
	move_note(&ctx, NOTE_INFO, "move.config", ctx.config_file, NULL, 0);
	move_note(&ctx, NOTE_WARNING, "warn.invalid", "/x", NULL, 0);
	report_notes(&r, &ctx, 0);
	CHECK(r.count == 3);
	if (r.count == 3) {
		CHECK(r.lines[0].indent == 0 && r.lines[1].indent == 1);
		CHECK_STR(r.lines[0].text, "/a/repo \342\206\222 /b/repo");
		CHECK(r.lines[2].level == NOTE_WARNING);
	}
	CHECK(report_count(&r, NOTE_WARNING) == 1);
	report_free(&r);
	report_notes(&r, &ctx, 1);
	CHECK(r.count == 0);

	file = xjoin(ctx.projects_dir, "-a-repo/s.jsonl");
	rewrite_text("{\"cwd\":\"/a/repo\"}", 17, REWRITE_SESSION, &rules, file,
	    1, &ctx.plan, &out, &len);
	free(out);
	rewrite_text("{\"cwd\":\"/a/repo/x\"}", 19, REWRITE_SESSION, &rules,
	    file, 2, &ctx.plan, &out, &len);
	free(out);
	rewrite_text("{\"projects\":{\"/a/repo\":{}}}", 27, REWRITE_CONFIG,
	    &rules, ctx.config_file, 0, &ctx.plan, &out, &len);
	free(out);
	report_plan(&r, &ctx);
	CHECK(r.count == 2);
	if (r.count == 2) {
		CHECK_STR(r.lines[0].text, "-a-repo/s.jsonl: cwd \303\2272");
		CHECK(r.lines[1].indent == 2);
		CHECK(strstr(r.lines[1].text,
		    "projects \342\200\234/a/repo\342\200\235") != NULL);
	}
	report_free(&r);
	free(file);
	move_free(&ctx);
}

static void test_msg(void)
{
	const char *help;
	size_t len;

	unsetenv("LC_ALL");
	unsetenv("LC_MESSAGES");
	setenv("LANG", "pl_PL.UTF-8", 1);
	msg_init();
	CHECK_STR(msg("error.nomem"), "zabrakło pamięci.");
	help = msg_help(NULL, &len);
	CHECK(strncmp(help, "csm — zarządza", strlen("csm — zarządza")) == 0);
	CHECK(len > 0 && help[len - 1] == '\n' && strncmp(help + len, "@ ", 2) == 0);
	help = msg_help("move", &len);
	CHECK(len > 0 && help[-1] == '\n' && strncmp(help + len, "@ fix\n", 6) == 0);
	CHECK_STR(msg("no.such.key"), "no.such.key");

	setenv("LC_MESSAGES", "en_US.UTF-8", 1);
	msg_init();
	CHECK_STR(msg("error.nomem"), "out of memory.");

	setenv("LC_ALL", "pl", 1);
	msg_init();
	CHECK_STR(msg("error.nomem"), "zabrakło pamięci.");

	setenv("LC_ALL", "", 1);
	setenv("LC_MESSAGES", "de_DE.UTF-8", 1);
	msg_init();
	CHECK_STR(msg("error.nomem"), "out of memory.");

	setenv("LC_MESSAGES", "C", 1);
	msg_init();
	CHECK_STR(msg("error.nomem"), "out of memory.");
}

static size_t keys(const char *bytes, int more, struct key *k)
{
	return key_decode((const unsigned char *)bytes, strlen(bytes), more, k);
}

static void test_keys(void)
{
	struct key k;

	CHECK(keys("q", 1, &k) == 1 && k.code == KEY_CHAR);
	CHECK_STR(k.text, "q");
	CHECK(keys("\303\263x", 1, &k) == 2 && k.code == KEY_CHAR);
	CHECK_STR(k.text, "\303\263");
	/* A character cut by the read waits for the rest, unless none comes. */
	CHECK(keys("\303", 1, &k) == 0);
	CHECK(keys("\303", 0, &k) == 1 && k.code == KEY_NONE);
	CHECK(keys("\377", 1, &k) == 1 && k.code == KEY_NONE);
	CHECK(keys("\r", 1, &k) == 1 && k.code == KEY_ENTER);
	CHECK(keys("\t", 1, &k) == 1 && k.code == KEY_TAB);
	CHECK(keys("\177", 1, &k) == 1 && k.code == KEY_BACKSPACE);
	CHECK(keys("\001", 1, &k) == 1 && k.code == KEY_CTRL);
	CHECK_STR(k.text, "a");
	CHECK(keys("\027", 1, &k) == 1 && k.code == KEY_CTRL);
	CHECK_STR(k.text, "w");
	CHECK(keys("\033\001", 0, &k) == 1 && k.code == KEY_ESC);
	CHECK(keys("\037", 1, &k) == 1 && k.code == KEY_NONE);

	CHECK(keys("\033[A", 1, &k) == 3 && k.code == KEY_UP);
	CHECK(keys("\033OB", 1, &k) == 3 && k.code == KEY_DOWN);
	CHECK(keys("\033[1;2C", 1, &k) == 6 && k.code == KEY_RIGHT);
	CHECK(keys("\033[5~", 1, &k) == 4 && k.code == KEY_PAGE_UP);
	CHECK(keys("\033[6;5~", 1, &k) == 6 && k.code == KEY_PAGE_DOWN);
	CHECK(keys("\033[1~", 1, &k) == 4 && k.code == KEY_HOME);
	CHECK(keys("\033[F", 1, &k) == 3 && k.code == KEY_END);
	CHECK(keys("\033[3~", 1, &k) == 4 && k.code == KEY_DELETE);
	CHECK(keys("\033[Z", 1, &k) == 3 && k.code == KEY_BACKTAB);
	/* Unknown sequences are eaten whole, not typed. */
	CHECK(keys("\033[2~", 1, &k) == 4 && k.code == KEY_NONE);
	CHECK(keys("\033[<0;12;5x", 1, &k) == 10 && k.code == KEY_NONE);

	/* SGR mouse reports: cells from 0, buttons, modifiers, the wheel. */
	CHECK(keys("\033[<0;12;5Mq", 1, &k) == 10 && k.code == KEY_MOUSE);
	CHECK(k.mouse == MOUSE_PRESS && k.button == 0 && k.x == 11 &&
	    k.y == 4 && k.mods == 0);
	CHECK(keys("\033[<0;12;5m", 1, &k) == 10 && k.mouse == MOUSE_RELEASE);
	CHECK(keys("\033[<32;3;7M", 1, &k) == 10 && k.mouse == MOUSE_DRAG &&
	    k.x == 2 && k.y == 6);
	CHECK(keys("\033[<64;1;1M", 1, &k) == 10 &&
	    k.mouse == MOUSE_WHEEL_UP);
	CHECK(keys("\033[<65;1;1M", 1, &k) == 10 &&
	    k.mouse == MOUSE_WHEEL_DOWN);
	CHECK(keys("\033[<4;1;1M", 1, &k) == 9 && k.mods == MOD_SHIFT);
	CHECK(keys("\033[<16;1;1M", 1, &k) == 10 && k.mods == MOD_CTRL);
	CHECK(keys("\033[<2;300;200M", 1, &k) == 13 && k.button == 2 &&
	    k.x == 299 && k.y == 199);
	/* A move with no button, a column 0, a cut report: nothing. */
	CHECK(keys("\033[<35;1;1M", 1, &k) == 10 && k.code == KEY_NONE);
	CHECK(keys("\033[<0;0;1M", 1, &k) == 9 && k.code == KEY_NONE);
	CHECK(keys("\033[<0;1M", 1, &k) == 7 && k.code == KEY_NONE);
	CHECK(keys("\033[<0;12", 1, &k) == 0);

	/* Esc alone only once nothing follows it. */
	CHECK(keys("\033", 1, &k) == 0);
	CHECK(keys("\033", 0, &k) == 1 && k.code == KEY_ESC);
	CHECK(keys("\033[1;", 1, &k) == 0);
	CHECK(keys("\033[1;", 0, &k) == 4 && k.code == KEY_NONE);
	CHECK(keys("\033q", 1, &k) == 1 && k.code == KEY_ESC);
	CHECK(keys("", 0, &k) == 0);

	/* The terminal's background, as OSC 11 answers: never a key. */
	CHECK(keys("\033]11;rgb:0000/0000/0000\033\\q", 1, &k) == 25 &&
	    k.code == KEY_BACKGROUND && k.dark == 1);
	CHECK(keys("\033]11;rgb:ffff/ffff/ffff\007", 1, &k) == 24 &&
	    k.code == KEY_BACKGROUND && k.dark == 0);
	CHECK(keys("\033]11;rgb:fe/fe/fe\007", 1, &k) == 18 &&
	    k.code == KEY_BACKGROUND && k.dark == 0);
	CHECK(keys("\033]11;rgba:1e1e/1e1e/1e1e/ffff\007", 1, &k) == 30 &&
	    k.code == KEY_BACKGROUND && k.dark == 1);
	/* Pure blue is dark, pure green light: green weighs most. */
	CHECK(keys("\033]11;rgb:0/0/f\007", 1, &k) == 15 && k.dark == 1);
	CHECK(keys("\033]11;rgb:0/f/0\007", 1, &k) == 15 && k.dark == 0);
	CHECK(keys("\033]11;rgb:00", 1, &k) == 0);
	CHECK(keys("\033]11;rgb:00\033", 1, &k) == 0);
	CHECK(keys("\033]11;rgb:00", 0, &k) == 11 && k.code == KEY_NONE);
	CHECK(keys("\033]10;rgb:0/0/0\007", 1, &k) == 15 &&
	    k.code == KEY_NONE);
	CHECK(keys("\033]11;rgb:zz/0/0\007", 1, &k) == 16 &&
	    k.code == KEY_NONE);
	CHECK(keys("\033]11;rgb:0/0\007", 1, &k) == 13 && k.code == KEY_NONE);
	CHECK(keys("\033]11;x\033q", 1, &k) == 6 && k.code == KEY_NONE);
}

static void check_flush(struct screen *s, const char *want, int line)
{
	char *out;
	size_t len;

	out = screen_flush(s, &len);
	test_check_str(out != NULL ? out : "", want, "flush", __FILE__, line);
	free(out);
}

#define CHECK_FLUSH(s, want) check_flush((s), (want), __LINE__)

static void test_screen(void)
{
	struct attr plain = { COLOR_DEFAULT, COLOR_DEFAULT, 0 };
	struct attr red = { COLOR_RED, COLOR_DEFAULT, STYLE_BOLD };
	struct attr grey = { COLOR_GRAY, COLOR_DEFAULT, 0 };
	struct screen s;

	if (setlocale(LC_CTYPE, "en_US.UTF-8") == NULL) {
		printf("unit: no en_US.UTF-8 locale, screen checks skipped\n");
		return;
	}
	screen_init(&s, 6, 2, 1);
	CHECK(screen_text(&s, 0, 0, 6, "ab", plain, 0) == 2);
	CHECK(screen_text(&s, 0, 1, 3, "7", plain, 1) == 3);
	CHECK_OWNED(screen_line(&s, 0), "ab");
	CHECK_OWNED(screen_line(&s, 1), "  7");
	/* The first frame sends everything, row by row. */
	CHECK_FLUSH(&s, "\033[1;1H\033[0mab    \033[2;1H  7   \033[?25l");
	CHECK_FLUSH(&s, "");

	/* Only the changed cells, with their attributes. */
	screen_clear(&s);
	screen_text(&s, 0, 0, 6, "ab", plain, 0);
	screen_text(&s, 0, 1, 3, "7", plain, 1);
	screen_text(&s, 4, 0, 2, "x", red, 0);
	CHECK_FLUSH(&s, "\033[1;5H\033[0;1;31mx \033[0m");
	screen_text(&s, 4, 0, 2, "xy", grey, 0);
	CHECK_FLUSH(&s, "\033[1;5H\033[0;90mxy\033[0m");
	/* A background of its own; the same text with it is a change too. */
	grey.bg = 254;
	screen_text(&s, 4, 0, 2, "xy", grey, 0);
	CHECK_FLUSH(&s, "\033[1;5H\033[0;90;48;5;254mxy\033[0m");
	grey.bg = COLOR_DEFAULT;

	/* Wide characters take two cells; a cut one leaves a space. */
	screen_clear(&s);
	screen_text(&s, 0, 1, 3, "7", plain, 1);
	CHECK(screen_text(&s, 0, 0, 3, "日本", plain, 0) == 3);
	CHECK_OWNED(screen_line(&s, 0), "日\342\200\246");
	CHECK(screen_text(&s, 0, 0, 2, "日本", plain, 0) == 1);
	CHECK_OWNED(screen_line(&s, 0), "\342\200\246 \342\200\246");
	CHECK(screen_text(&s, 0, 0, 6, "日本", plain, 0) == 4);
	CHECK_OWNED(screen_line(&s, 0), "日本");
	CHECK_FLUSH(&s, "\033[1;1H\033[0m日本  ");
	screen_text(&s, 1, 0, 1, "z", plain, 0);
	CHECK_OWNED(screen_line(&s, 0), " z本");
	CHECK_FLUSH(&s, "\033[1;1H\033[0m z");
	screen_text(&s, 0, 0, 6, "e\314\201!", plain, 0);
	CHECK_OWNED(screen_line(&s, 0), "e\314\201!");

	/* The cursor shows only where text is typed. */
	s.cursor_on = 1;
	s.cursor_x = 2;
	s.cursor_y = 1;
	CHECK_FLUSH(&s, "\033[1;1H\033[0me\314\201!  \033[2;3H\033[?25h");
	s.cursor_on = 1;
	CHECK_FLUSH(&s, "");
	screen_clear(&s);
	screen_text(&s, 0, 0, 6, "e\314\201!", plain, 0);
	screen_text(&s, 0, 1, 3, "7", plain, 1);
	CHECK_FLUSH(&s, "\033[?25l");

	/* NO_COLOR keeps the styles, drops the colours. */
	screen_free(&s);
	screen_init(&s, 2, 1, 0);
	screen_text(&s, 0, 0, 2, "x", red, 0);
	CHECK_FLUSH(&s, "\033[1;1H\033[0;1mx \033[0m\033[?25l");
	screen_resize(&s, 3, 1);
	CHECK_FLUSH(&s, "\033[1;1H\033[0m   \033[?25l");
	screen_free(&s);
	setlocale(LC_CTYPE, "C");
}

static struct key key_char(const char *c)
{
	struct key k;

	k.code = KEY_CHAR;
	snprintf(k.text, sizeof k.text, "%s", c);
	return k;
}

static void press_key(struct tui *t, enum key_code code)
{
	struct key k;

	k.code = code;
	k.text[0] = '\0';
	tui_key(t, &k);
}

static void press_char(struct tui *t, const char *c)
{
	struct key k = key_char(c);

	tui_key(t, &k);
}

/* The project shown in list row n (0 is the first directory). */
static const char *row_dir(const struct tui *t, size_t n)
{
	return n < t->view_count ? t->inv.dirs[t->view[n]].name : "";
}

static int line_has(struct screen *s, size_t y, const char *text)
{
	char *line;
	int found;

	line = screen_line(s, y);
	found = strstr(line, text) != NULL;
	if (!found)
		printf("unit: line %zu: \"%s\" lacks \"%s\"\n", y, line, text);
	free(line);
	return found;
}

static void test_tui_columns(void)
{
	static const size_t natural[TUI_COLUMNS] = { 10, 40, 6, 8, 16 };
	static const size_t drop[] = { 4, 3, 2 };
	size_t out[TUI_COLUMNS];

	tui_fit_columns(natural, TUI_COLUMNS, 1, drop, 3, 100, out);
	CHECK(out[0] == 10 && out[1] == 52 && out[4] == 16);
	tui_fit_columns(natural, TUI_COLUMNS, 1, drop, 3, 64, out);
	CHECK(out[1] == 16 && out[4] == 16);
	/* Too narrow: the last columns make room, the flexible one fills it. */
	tui_fit_columns(natural, TUI_COLUMNS, 1, drop, 3, 63, out);
	CHECK(out[4] == 0 && out[3] == 8 && out[1] == 33);
	tui_fit_columns(natural, TUI_COLUMNS, 1, drop, 3, 20, out);
	CHECK(out[4] == 0 && out[3] == 0 && out[2] == 0 && out[1] == 8);
	tui_fit_columns(natural, TUI_COLUMNS, 1, drop, 3, 5, out);
	CHECK(out[0] == 10 && out[1] == 0);

	CHECK(tui_match("/Users/m/Repo", ""));
	CHECK(tui_match("/Users/m/Repo", "rEPo"));
	CHECK(tui_match("/Users/m/Repo", "/m/"));
	CHECK(!tui_match("/Users/m/Repo", "repos"));
	CHECK(!tui_match("", "a"));
	/* Only ASCII letters ignore case; the rest is compared byte by byte. */
	CHECK(tui_match("Zażółć", "ŻÓŁ") == 0);
	CHECK(tui_match("Zażółć", "żół"));
}

/* Three directories: active with two sessions, orphaned, unknown. */
static void test_tui(void)
{
	struct tui t;
	struct screen s;
	char *base, *config, *projects, *alpha, *gone, *name, *dir, *line;
	char *saved;
	size_t cap;

	saved = xstrdup(getenv("CLAUDE_CONFIG_DIR"));
	base = make_dir(work, "tui");
	config = make_dir(base, "config");
	projects = make_dir(config, "projects");
	alpha = make_dir(base, "alpha");
	gone = xjoin(base, "gone");
	setenv("CLAUDE_CONFIG_DIR", config, 1);
	setenv("LC_ALL", "en_US.UTF-8", 1);
	msg_init();
	if (setlocale(LC_CTYPE, "en_US.UTF-8") == NULL) {
		printf("unit: no en_US.UTF-8 locale, TUI checks skipped\n");
		goto done;
	}

	cap = strlen(base) + 256;
	line = xmalloc(cap);
	name = path_encode(alpha);
	dir = make_dir(projects, name);
	snprintf(line, cap, "{\"type\":\"user\",\"cwd\":\"%s\",\"timestamp\":"
	    "\"2026-10-27T20:00:00Z\",\"message\":{\"content\":\"Hello alpha\"}}\n",
	    alpha);
	write_file(dir, "s1.jsonl", line);
	write_file(dir, "s2.jsonl", line);
	free(dir);
	free(name);
	name = path_encode(gone);
	dir = make_dir(projects, name);
	snprintf(line, cap, "{\"type\":\"user\",\"cwd\":\"%s\",\"message\":"
	    "{\"content\":\"x\"}}\n", gone);
	write_file(dir, "s3.jsonl", line);
	free(dir);
	free(name);
	dir = make_dir(projects, "-x-unknown");
	free(make_dir(dir, "memory"));
	free(dir);
	free(line);

	tui_init(&t);
	CHECK(t.inv.count == 3 && t.view_count == 3);
	CHECK(t.check_claude);
	tui_set_claude(&t, 0, 0);
	name = path_encode(alpha);
	CHECK_STR(row_dir(&t, 0), name);
	free(name);
	CHECK_STR(row_dir(&t, 2), "-x-unknown");

	screen_init(&s, 160, 20, 1);
	tui_render(&t, &s);
	CHECK(line_has(&s, 0, "csm \342\200\224 "));
	CHECK(line_has(&s, 1, "STATE"));
	CHECK(line_has(&s, 1, "PROJECT \342\226\262"));
	CHECK(line_has(&s, 2, "active"));
	CHECK(line_has(&s, 2, alpha));
	CHECK(line_has(&s, 3, "orphaned"));
	CHECK(line_has(&s, 4, "-x-unknown"));
	CHECK(s.back[2 * s.cols].attr.bg == tui_theme(&t)->select);
	CHECK(s.back[3 * s.cols + TUI_MARK].attr.fg == tui_theme(&t)->red);
	CHECK(line_has(&s, 18, "m Move"));
	CHECK(line_has(&s, 18, "t Trash"));
	/* Fix is for orphans only: greyed while an active project is chosen. */
	CHECK(s.back[18 * s.cols + t.buttons[0].x0].attr.fg == COLOR_DEFAULT);
	CHECK(s.back[18 * s.cols + t.buttons[1].x0].attr.fg ==
	    tui_theme(&t)->bar_grey);
	/* The bar has its own background across the screen, with separators. */
	CHECK(s.back[18 * s.cols].attr.bg == tui_theme(&t)->bar);
	CHECK(s.back[18 * s.cols + s.cols - 1].attr.bg == tui_theme(&t)->bar);
	CHECK(line_has(&s, 18, "Move \342\224\202 f Fix"));
	CHECK(s.back[17 * s.cols].attr.bg == COLOR_DEFAULT);
	CHECK(line_has(&s, 19, "Enter details"));
	/* The sessions wait for the first frame, then come in full. */
	CHECK(line_has(&s, 15, "Reading sessions"));
	CHECK(tui_wanted(&t) == (long)t.view[0]);
	tui_load(&t, (size_t)tui_wanted(&t));
	CHECK(tui_wanted(&t) == -1);
	tui_render(&t, &s);
	CHECK(line_has(&s, 13, "State: active"));
	CHECK(line_has(&s, 13, "Sessions: 2"));
	CHECK(line_has(&s, 14, "NAME  FIRST PROMPT"));
	CHECK(line_has(&s, 15, "Hello alpha"));
	CHECK(line_has(&s, 16, "Hello alpha"));

	/* Another Claude Code version: a yellow row under the title. */
	t.version_warning = xstrdup("Claude Code is version 9.9.9");
	tui_render(&t, &s);
	CHECK(line_has(&s, 1, "Claude Code is version 9.9.9"));
	CHECK(s.back[1 * s.cols].attr.bg == tui_theme(&t)->notice);
	CHECK(s.back[1 * s.cols + s.cols - 1].attr.bg ==
	    tui_theme(&t)->notice);
	CHECK(line_has(&s, 2, "PROJECT"));
	CHECK(t.list_y == 2);
	CHECK(line_has(&s, 18, "m Move"));
	free(t.version_warning);
	t.version_warning = NULL;
	tui_render(&t, &s);
	CHECK(line_has(&s, 1, "PROJECT"));

	/* Moving and sorting keep the selected directory. */
	press_key(&t, KEY_DOWN);
	CHECK(t.cursor == 1);
	press_key(&t, KEY_END);
	CHECK(t.cursor == 2);
	press_key(&t, KEY_DOWN);
	CHECK(t.cursor == 2);
	press_key(&t, KEY_HOME);
	press_char(&t, "o");
	CHECK(t.sort == SORT_SESSIONS);
	CHECK_STR(row_dir(&t, 2), "-x-unknown");
	tui_render(&t, &s);
	CHECK(line_has(&s, 1, "SESSIONS \342\226\274"));
	press_char(&t, "O");
	CHECK_STR(row_dir(&t, 0), "-x-unknown");
	CHECK(t.cursor == 2);
	press_char(&t, "o");
	press_char(&t, "o");
	press_char(&t, "o");
	CHECK(t.sort == SORT_STATE && !t.reverse);
	CHECK_STR(row_dir(&t, 2), "-x-unknown");
	press_char(&t, "o");
	CHECK(t.sort == SORT_PROJECT);
	CHECK(t.cursor == 0);

	/* The filter narrows the list as it is typed. */
	press_char(&t, "/");
	CHECK(t.mode == MODE_FILTER);
	press_char(&t, "G");
	press_char(&t, "o");
	CHECK(t.view_count == 1);
	CHECK(t.sort == SORT_PROJECT);
	tui_render(&t, &s);
	CHECK(line_has(&s, 19, "Filter: Go"));
	CHECK(s.cursor_on && s.cursor_y == 19);
	press_char(&t, "x");
	CHECK(t.view_count == 0);
	tui_render(&t, &s);
	CHECK(line_has(&s, 2, "Nothing matches the filter \342\200\234Gox\342\200\235"));
	press_key(&t, KEY_BACKSPACE);
	press_key(&t, KEY_ENTER);
	CHECK(t.mode == MODE_BROWSE && t.view_count == 1);
	tui_render(&t, &s);
	CHECK(line_has(&s, 0, "Filter: Go"));
	CHECK(line_has(&s, 19, "Showing 1 of 3"));
	CHECK(!s.cursor_on);
	press_key(&t, KEY_ESC);
	CHECK(t.view_count == 3 && t.filter[0] == '\0');

	/* Details take the arrows; Esc goes back. */
	CHECK(t.cursor == 1);
	press_key(&t, KEY_HOME);
	press_key(&t, KEY_ENTER);
	CHECK(t.focus == FOCUS_DETAILS);
	press_key(&t, KEY_DOWN);
	CHECK(t.detail_cursor == 1 && t.cursor == 0);
	tui_render(&t, &s);
	CHECK(line_has(&s, 19, "Tab or Esc"));
	CHECK(s.back[16 * s.cols].attr.bg == tui_theme(&t)->select);
	CHECK(s.back[2 * s.cols].attr.style == STYLE_BOLD);
	press_key(&t, KEY_ESC);
	CHECK(t.focus == FOCUS_LIST);
	press_key(&t, KEY_TAB);
	CHECK(t.focus == FOCUS_DETAILS);
	press_key(&t, KEY_TAB);
	CHECK(t.focus == FOCUS_LIST);

	/* One place for messages: error, then warning, then the hint. */
	tui_set_claude(&t, 1, 0);
	tui_render(&t, &s);
	CHECK(line_has(&s, 19, "Claude Code is running"));
	press_char(&t, "m");
	CHECK(t.mode == MODE_BROWSE);
	tui_render(&t, &s);
	CHECK(line_has(&s, 19, "quit it first"));
	press_char(&t, "h");
	CHECK(t.screen == SCREEN_HELP);
	tui_render(&t, &s);
	CHECK(line_has(&s, 0, "csm \342\200\224 help"));
	CHECK(line_has(&s, 1, "csm \342\200\224 manages Claude Code"));
	CHECK(line_has(&s, 19, "Claude Code is running"));
	press_key(&t, KEY_ESC);
	CHECK(t.screen == SCREEN_LIST && t.cursor == 0);
	press_key(&t, KEY_DOWN);
	tui_render(&t, &s);
	CHECK(line_has(&s, 19, "Claude Code is running"));
	tui_set_claude(&t, -1, EACCES);
	tui_render(&t, &s);
	CHECK(line_has(&s, 19, "cannot tell whether Claude Code is running"));
	tui_set_claude(&t, 0, 0);

	/* Refresh keeps the selection; a vanished directory goes away. */
	CHECK(t.cursor == 1);
	dir = xjoin(projects, "-x-unknown/memory");
	CHECK(rmdir(dir) == 0);
	free(dir);
	dir = xjoin(projects, "-x-unknown");
	CHECK(rmdir(dir) == 0);
	free(dir);
	press_char(&t, "l");
	CHECK(t.inv.count == 2 && t.cursor == 1 && t.check_claude);
	press_char(&t, "q");
	CHECK(t.quit);

	screen_resize(&s, 30, 8);
	tui_render(&t, &s);
	CHECK(line_has(&s, 0, "The terminal window"));
	screen_free(&s);
	tui_free(&t);
	setlocale(LC_CTYPE, "C");
done:
	setenv("CLAUDE_CONFIG_DIR", saved, 1);
	free(saved);
	free(gone);
	free(alpha);
	free(projects);
	free(config);
	free(base);
}

static int claude_off(void)
{
	return 0;
}

static int claude_on(void)
{
	return 1;
}

static void mouse_at(struct tui *t, enum mouse_event ev, size_t x, size_t y,
    unsigned mods, long ms)
{
	struct key k;

	memset(&k, 0, sizeof k);
	k.code = KEY_MOUSE;
	k.mouse = ev;
	k.x = x;
	k.y = y;
	k.mods = mods;
	k.ms = ms;
	tui_key(t, &k);
}

static void click_at(struct tui *t, size_t x, size_t y, unsigned mods, long ms)
{
	mouse_at(t, MOUSE_PRESS, x, y, mods, ms);
	mouse_at(t, MOUSE_RELEASE, x, y, mods, ms);
}

/* A session directory of project with one session. */
static void add_session_dir(const char *projects, const char *project)
{
	char *name, *dir, *line;
	size_t cap = strlen(project) + 64;

	name = path_encode(project);
	dir = make_dir(projects, name);
	line = xmalloc(cap);
	snprintf(line, cap, "{\"type\":\"user\",\"cwd\":\"%s\"}\n", project);
	write_file(dir, "s.jsonl", line);
	free(line);
	free(dir);
	free(name);
}

static int exists(const char *path)
{
	struct stat st;

	return lstat(path, &st) == 0;
}

static size_t view_of(const struct tui *t, const char *project)
{
	size_t i;

	for (i = 0; i < t->view_count; i++)
		if (t->inv.dirs[t->view[i]].project != NULL &&
		    strcmp(t->inv.dirs[t->view[i]].project, project) == 0)
			return i;
	return (size_t)-1;
}

/* Puts the cursor on the directory of project with a click. */
static void pick(struct tui *t, struct screen *s, const char *project)
{
	size_t i = view_of(t, project);

	tui_render(t, s);
	CHECK(i != (size_t)-1);
	if (i != (size_t)-1)
		click_at(t, 10, t->list_y + 1 + i - t->top, 0, 100000);
	CHECK(t->cursor == i);
}

/*
 * The mouse and the changes of stage 7: clicks, marks, the border, the
 * path field with completion, plans, questions, the trash screen and the
 * githubRepoPaths proposal, on real directories below the work dir.
 */
static void test_tui_actions(void)
{
	struct tui t;
	struct screen s;
	char *base, *config, *projects, *repo, *gone, *sub, *other, *moved;
	char *found, *json, *data, *path, *saved, *line;
	size_t cap, len, i;

	saved = xstrdup(getenv("CLAUDE_CONFIG_DIR"));
	base = make_dir(work, "tui2");
	config = make_dir(base, "config");
	projects = make_dir(config, "projects");
	repo = make_dir(base, "repo");
	gone = xjoin(base, "gone");
	sub = make_dir(base, "sub");
	other = make_dir(sub, "other");
	found = make_dir(sub, "gone");
	moved = xjoin(base, "moved");
	setenv("CLAUDE_CONFIG_DIR", config, 1);
	setenv("LC_ALL", "en_US.UTF-8", 1);
	msg_init();
	if (setlocale(LC_CTYPE, "en_US.UTF-8") == NULL) {
		printf("unit: no en_US.UTF-8 locale, TUI checks skipped\n");
		goto done;
	}
	add_session_dir(projects, repo);
	add_session_dir(projects, gone);
	add_session_dir(projects, other);
	cap = 2 * strlen(base) + 128;
	json = xmalloc(cap);
	snprintf(json, cap, "{\"projects\":{\"%s\":{\"a\":1}},"
	    "\"githubRepoPaths\":{\"o/r\":[\"%s/missing\"]}}", gone, base);
	write_file(config, ".claude.json", json);

	tui_init(&t);
	t.claude_now = claude_off;
	tui_set_claude(&t, 0, 0);
	CHECK(t.view_count == 3 && t.github_dead == 1);
	screen_init(&s, 120, 24, 1);
	tui_render(&t, &s);
	CHECK(line_has(&s, 23, "no longer exist: 1"));

	/* Clicks choose, Ctrl adds one, Shift a range from the last click. */
	click_at(&t, 10, 3, 0, 1000);
	CHECK(t.cursor == 1 && t.focus == FOCUS_LIST);
	click_at(&t, 10, 2, MOD_CTRL, 2000);
	CHECK(t.cursor == 0 && t.marked[t.view[0]]);
	click_at(&t, 10, 4, MOD_SHIFT, 3000);
	CHECK(t.cursor == 2);
	CHECK(t.marked[0] && t.marked[1] && t.marked[2]);
	tui_render(&t, &s);
	CHECK(line_has(&s, 3, "\342\234\223 "));
	CHECK(line_has(&s, 23, "Marked: 3"));
	press_char(&t, " ");
	CHECK(!t.marked[t.view[2]] && t.cursor == 2);
	/* Space toggles the chosen row and leaves the choice where it is. */
	press_key(&t, KEY_HOME);
	press_char(&t, " ");
	CHECK(!t.marked[t.view[0]] && t.cursor == 0);
	press_char(&t, " ");
	CHECK(t.marked[t.view[0]] && t.cursor == 0);
	memset(t.marked, 0, t.inv.count);

	/* A double click opens the details; a click on the header sorts. */
	click_at(&t, 10, 3, 0, 5000);
	click_at(&t, 10, 3, 0, 5200);
	CHECK(t.cursor == 1 && t.focus == FOCUS_DETAILS);
	click_at(&t, 10, 3, 0, 5300);
	CHECK(t.focus == FOCUS_LIST);
	tui_render(&t, &s);
	click_at(&t, t.col_x[SORT_SESSIONS], 1, 0, 6000);
	CHECK(t.sort == SORT_SESSIONS && !t.reverse);
	click_at(&t, t.col_x[SORT_SESSIONS] + 1, 1, 0, 7000);
	CHECK(t.sort == SORT_SESSIONS && t.reverse);
	click_at(&t, t.col_x[SORT_PROJECT], 1, 0, 8000);
	CHECK(t.sort == SORT_PROJECT && !t.reverse);

	/* The border follows the mouse; the wheel scrolls under the pointer. */
	tui_render(&t, &s);
	CHECK(t.list_rows == 10 && t.sep_y == 12);
	mouse_at(&t, MOUSE_PRESS, 5, 12, 0, 9000);
	mouse_at(&t, MOUSE_DRAG, 5, 4, 0, 9000);
	mouse_at(&t, MOUSE_RELEASE, 5, 4, 0, 9000);
	tui_render(&t, &s);
	CHECK(t.list_rows == 2 && t.sep_y == 4);
	press_key(&t, KEY_HOME);
	mouse_at(&t, MOUSE_WHEEL_DOWN, 5, 2, 0, 9100);
	tui_render(&t, &s);
	CHECK(t.top == 1 && t.cursor == 0);
	press_key(&t, KEY_DOWN);
	press_key(&t, KEY_UP);
	tui_render(&t, &s);
	CHECK(t.top == 0);
	mouse_at(&t, MOUSE_PRESS, 5, 4, 0, 9200);
	mouse_at(&t, MOUSE_DRAG, 5, 30, 0, 9200);
	tui_render(&t, &s);
	CHECK(t.list_rows == 18);
	mouse_at(&t, MOUSE_DRAG, 5, 0, 0, 9200);
	mouse_at(&t, MOUSE_RELEASE, 5, 0, 0, 9200);
	tui_render(&t, &s);
	CHECK(t.list_rows == 1);
	mouse_at(&t, MOUSE_DRAG, 5, 12, 0, 9300);
	tui_render(&t, &s);
	CHECK(t.list_rows == 1);
	t.split = 500;

	/* Buttons are clicked like their keys. */
	tui_render(&t, &s);
	for (i = 0; i < t.button_count && strcmp(t.buttons[i].keytext, "/");
	    i++)
		;
	CHECK(i < t.button_count);
	click_at(&t, t.buttons[i].x0, 22, 0, 10000);
	CHECK(t.mode == MODE_FILTER);
	press_key(&t, KEY_ESC);

	/* Move: the field starts with the project, Tab completes, a plan. */
	pick(&t, &s, repo);
	press_char(&t, "m");
	CHECK(t.mode == MODE_FIELD);
	CHECK_STR(t.field.text, repo);
	tui_render(&t, &s);
	CHECK(line_has(&s, 23, "To: "));
	CHECK(s.cursor_on && s.cursor_y == 23);
	field_press(&t.field, KEY_CTRL, "w");
	press_char(&t, "z");
	press_key(&t, KEY_TAB);
	tui_render(&t, &s);
	CHECK(line_has(&s, 23, "No directory matches"));
	press_key(&t, KEY_BACKSPACE);
	press_char(&t, "s");
	press_key(&t, KEY_TAB);
	path = xjoin(sub, "");
	CHECK_STR(t.field.text, path);
	free(path);
	press_key(&t, KEY_TAB);
	CHECK(t.completing && t.suggest_count == 2);
	tui_render(&t, &s);
	CHECK(line_has(&s, t.items_y - 1, "Matching directories"));
	click_at(&t, 5, t.items_y + 1, 0, 11000);
	CHECK(strstr(t.field.text, "/sub/other/") != NULL);
	press_key(&t, KEY_UP);
	CHECK(strstr(t.field.text, "/sub/gone/") != NULL);
	press_char(&t, "x");
	CHECK(!t.completing && t.suggest_count == 0);
	field_set(&t.field, moved);
	press_key(&t, KEY_ENTER);
	CHECK(t.mode == MODE_PLAN && !t.confirm && t.preview.count > 0);
	tui_render(&t, &s);
	CHECK(line_has(&s, t.lower_y, "Plan of the move"));
	CHECK(line_has(&s, 23, "Enter runs it"));
	press_key(&t, KEY_ESC);
	CHECK(t.mode == MODE_BROWSE && exists(repo) && !exists(moved));

	/* Claude Code started meanwhile: the change does not happen. */
	t.claude_now = claude_on;
	press_char(&t, "m");
	field_set(&t.field, moved);
	press_key(&t, KEY_ENTER);
	press_key(&t, KEY_ENTER);
	CHECK(t.claude && exists(repo) && !exists(moved));
	tui_render(&t, &s);
	CHECK(line_has(&s, 23, "quit it first"));
	t.claude_now = claude_off;
	tui_set_claude(&t, 0, 0);

	pick(&t, &s, repo);
	press_char(&t, "m");
	field_set(&t.field, moved);
	press_key(&t, KEY_ENTER);
	press_key(&t, KEY_ENTER);
	CHECK(t.mode == MODE_BROWSE && !exists(repo) && exists(moved));
	CHECK(view_of(&t, moved) != (size_t)-1);
	tui_render(&t, &s);
	CHECK(line_has(&s, 23, "Moved: "));

	/* A plan with an error goes back to the field. */
	pick(&t, &s, moved);
	press_char(&t, "m");
	path = xjoin(base, "nope/x");
	field_set(&t.field, path);
	free(path);
	press_key(&t, KEY_ENTER);
	tui_render(&t, &s);
	CHECK(line_has(&s, 23, "This cannot be done"));
	CHECK(line_has(&s, 22, "Enter Correct"));
	press_key(&t, KEY_ENTER);
	CHECK(t.mode == MODE_FIELD);
	press_key(&t, KEY_ESC);

	/* Fix: only an orphan, with the folder of the same name proposed. */
	press_char(&t, "f");
	CHECK(t.mode == MODE_BROWSE && t.error != NULL);
	pick(&t, &s, gone);
	press_char(&t, "f");
	CHECK(t.mode == MODE_FIELD && t.field.len == 0);
	CHECK(t.suggest_count == 1);
	tui_render(&t, &s);
	CHECK(line_has(&s, t.items_y - 1, "Possible new places"));
	press_key(&t, KEY_ENTER);
	CHECK(t.mode == MODE_FIELD && t.error != NULL);
	press_key(&t, KEY_DOWN);
	CHECK_STR(t.field.text, found);
	press_key(&t, KEY_ENTER);
	press_key(&t, KEY_ENTER);
	CHECK(t.mode == MODE_BROWSE && view_of(&t, found) != (size_t)-1);
	CHECK(file_read(t.paths.config_file, &data, &len) == 0);
	CHECK(strstr(data, found) != NULL);
	free(data);

	/* Remove asks; Return is No, Yes needs an arrow or a click. */
	pick(&t, &s, other);
	press_char(&t, "r");
	CHECK(t.mode == MODE_PLAN && t.confirm && !t.yes);
	tui_render(&t, &s);
	/*
	 * An alert in the middle of the upper panel, the plan in sight below;
	 * the answer with the focus blue and bold, the other grey.
	 */
	CHECK(t.answers_y > t.list_y && t.answers_y < t.sep_y);
	CHECK(line_has(&s, t.answers_y, "[ No ]   [ Yes ]"));
	CHECK(line_has(&s, t.answers_y - 2, "Move these session directories"));
	CHECK(line_has(&s, t.answers_y - 4, "\342\224\214\342\224\200"));
	CHECK(s.back[t.answers_y * s.cols + t.no_x0].attr.bg ==
	    tui_theme(&t)->select);
	CHECK(s.back[t.answers_y * s.cols + t.no_x0].attr.style & STYLE_BOLD);
	CHECK(s.back[t.answers_y * s.cols + t.yes_x0].attr.bg ==
	    tui_theme(&t)->bar);
	CHECK(s.back[t.answers_y * s.cols + t.yes_x1].attr.bg == COLOR_DEFAULT);
	/* The answers do not run over the frame on the right. */
	line = screen_line(&s, t.answers_y);
	CHECK(strlen(line) > 3 &&
	    strcmp(line + strlen(line) - 3, "\342\224\202") == 0);
	free(line);
	CHECK(t.no_x0 * 2 + (t.yes_x1 - t.no_x0) <= s.cols + 1 &&
	    t.no_x0 * 2 + (t.yes_x1 - t.no_x0) >= s.cols - 1);
	CHECK(line_has(&s, 23, "Enter confirms"));
	CHECK(line_has(&s, t.lower_y + 1, "to the trash"));
	press_key(&t, KEY_ENTER);
	CHECK(t.mode == MODE_BROWSE && view_of(&t, other) != (size_t)-1);
	CHECK_STR(t.info, "Nothing has changed.");
	press_char(&t, "r");
	press_key(&t, KEY_RIGHT);
	CHECK(t.yes);
	press_key(&t, KEY_ENTER);
	CHECK(view_of(&t, other) == (size_t)-1 && t.inv.count == 2);
	CHECK(t.info != NULL && strstr(t.info, "in the trash: 1") != NULL);

	/* The trash: Enter restores the entry; E deletes for good. */
	press_char(&t, "t");
	CHECK(t.screen == SCREEN_TRASH && t.trash.count == 1);
	tui_render(&t, &s);
	CHECK(line_has(&s, 0, "trash"));
	CHECK(line_has(&s, 2, "sub-other"));
	CHECK(line_has(&s, 23, "in the trash"));
	press_key(&t, KEY_ENTER);
	CHECK(t.mode == MODE_PLAN && !t.confirm);
	press_key(&t, KEY_ENTER);
	CHECK(t.screen == SCREEN_TRASH && t.trash.count == 0);
	CHECK(view_of(&t, other) != (size_t)-1);
	press_char(&t, "E");
	CHECK(t.mode == MODE_BROWSE && t.error != NULL);
	press_key(&t, KEY_ESC);
	CHECK(t.screen == SCREEN_LIST);
	pick(&t, &s, other);
	press_char(&t, "r");
	press_key(&t, KEY_TAB);
	press_key(&t, KEY_ENTER);
	press_char(&t, "t");
	CHECK(t.trash.count == 1);
	press_char(&t, "E");
	CHECK(t.confirm);
	tui_render(&t, &s);
	click_at(&t, t.yes_x0, t.answers_y, 0, 20000);
	CHECK(t.mode == MODE_BROWSE && t.trash.count == 0);
	press_key(&t, KEY_ESC);

	/* The saved GitHub path that is gone: U, a question, then it goes. */
	press_char(&t, "U");
	CHECK(t.mode == MODE_PLAN && t.confirm);
	tui_render(&t, &s);
	CHECK(line_has(&s, t.lower_y + 1, "/missing (o/r)"));
	press_key(&t, KEY_LEFT);
	press_key(&t, KEY_ENTER);
	CHECK(t.github_dead == 0);
	CHECK(file_read(t.paths.config_file, &data, &len) == 0);
	CHECK(strstr(data, "\"o/r\":[]") != NULL);
	free(data);
	press_char(&t, "U");
	CHECK(t.mode == MODE_BROWSE && t.error != NULL);

	screen_free(&s);
	tui_free(&t);
	free(json);
	setlocale(LC_CTYPE, "C");
done:
	setenv("CLAUDE_CONFIG_DIR", saved, 1);
	free(saved);
	free(moved);
	free(found);
	free(other);
	free(sub);
	free(gone);
	free(repo);
	free(projects);
	free(config);
	free(base);
}

static void test_settings(void)
{
	struct settings st;
	struct tui t;
	struct screen s;
	struct key k;
	char *dir, *path, *data, *line, want[64];
	const char *at;
	size_t len, y;

	CHECK(screen_nearest(0x000000) == 16);
	CHECK(screen_nearest(0xffffff) == 231);
	CHECK(screen_nearest(0xff0000) == 196);
	CHECK(screen_nearest(0x808080) == 244);
	CHECK(screen_nearest(0x2e3440) == 237);
	CHECK(background_dark("15;0") == 1);
	CHECK(background_dark("0;15") == 0);
	CHECK(background_dark("0;default;8") == 1);
	CHECK(background_dark("0;default;7") == 0);
	CHECK(background_dark(NULL) == -1);
	CHECK(background_dark("15") == -1);
	CHECK(background_dark("15;") == -1);
	CHECK(background_dark("0;16") == -1);
	CHECK(background_dark("0;1x") == -1);

	/* Unknown keys and values change nothing; the last word wins. */
	settings_default(&st);
	CHECK(st.theme == THEME_AUTO);
	data = " theme = dark \r\n# theme=light\nfoo=bar\ntheme=nope\nx";
	settings_parse(&st, data, strlen(data));
	CHECK(st.theme == THEME_DARK);
	settings_parse(&st, "theme=light", 11);
	CHECK(st.theme == THEME_LIGHT);
	data = settings_text(&st);
	CHECK_STR(data, "theme=light\n");
	free(data);
	/* The keys of the themes that are gone are unknown now. */
	data = "light_theme=gruvbox\ndark_theme=dracula\ntheme=system\n";
	settings_parse(&st, data, strlen(data));
	CHECK(st.theme == THEME_SYSTEM);
	settings_default(&st);
	path = settings_path("/h");
	CHECK(path != NULL && strlen(path) > 13 &&
	    strcmp(path + strlen(path) - 13, "/csm/settings") == 0);
	free(path);
	CHECK(settings_path(NULL) == NULL || getenv("XDG_DATA_HOME") != NULL);

	/* Save makes the directories; a missing file is the defaults. */
	dir = make_dir(work, "settings");
	path = xjoin(dir, "a/b/settings");
	CHECK(settings_load(path, &st) == 0 && st.theme == THEME_AUTO);
	st.theme = THEME_DARK;
	CHECK(settings_save(path, &st) == 0);
	st.theme = THEME_AUTO;
	CHECK(settings_load(path, &st) == 0 && st.theme == THEME_DARK);
	CHECK(file_read(path, &data, &len) == 0);
	CHECK_STR(data, "theme=dark\n");
	free(data);
	free(path);
	free(dir);

	setenv("LC_ALL", "en_US.UTF-8", 1);
	msg_init();
	if (setlocale(LC_CTYPE, "en_US.UTF-8") == NULL) {
		printf("unit: no en_US.UTF-8 locale, settings checks skipped\n");
		return;
	}
	tui_init(&t);
	tui_set_claude(&t, 0, 0);
	CHECK(t.settings.theme == THEME_AUTO && t.background == -1);
	CHECK(!tui_dark(&t) && tui_theme(&t) == &theme_light);
	screen_init(&s, 120, 24, 1);
	tui_render(&t, &s);
	CHECK(line_has(&s, 22, ", Settings"));
	/* The title is a bar like the buttons; the cursor is the chosen row. */
	CHECK(s.fg == theme_light.fg && s.bg == theme_light.bg);
	CHECK(s.back[0].attr.bg == theme_light.bar);
	press_char(&t, ",");
	CHECK(t.screen == SCREEN_SETTINGS);
	tui_render(&t, &s);
	CHECK(line_has(&s, 0, "settings: ~/"));
	CHECK(line_has(&s, 1, "Appearance"));
	CHECK(line_has(&s, 2, "  Theme"));
	CHECK(line_has(&s, 2, "Automatic (background unknown, light)"));
	CHECK(!line_has(&s, 2, "Dark"));
	CHECK(line_has(&s, 22, "Esc List"));
	CHECK(line_has(&s, 23, "Space changes"));
	/* The samples carry the colours of the theme. */
	y = t.lower_y + 3;
	line = screen_line(&s, y);
	at = strstr(line, "orphaned");
	CHECK(at != NULL);
	if (at != NULL)
		CHECK(s.back[y * s.cols + (size_t)(at - line)].attr.fg ==
		    theme_light.red);
	free(line);

	/* The terminal tells a dark background: automatic follows it. */
	memset(&k, 0, sizeof k);
	k.code = KEY_BACKGROUND;
	k.dark = 1;
	tui_key(&t, &k);
	CHECK(t.answered && tui_dark(&t) && tui_theme(&t) == &theme_dark);
	tui_render(&t, &s);
	CHECK(line_has(&s, 2, "Automatic (dark background)"));
	line = screen_line(&s, y);
	at = strstr(line, "orphaned");
	if (at != NULL)
		CHECK(s.back[y * s.cols + (size_t)(at - line)].attr.fg ==
		    theme_dark.red);
	free(line);

	/* System leaves the terminal's own colours, by its background. */
	press_key(&t, KEY_RIGHT);
	CHECK(t.settings.theme == THEME_SYSTEM && tui_dark(&t));
	CHECK(tui_theme(&t) == &theme_system_dark);
	CHECK(t.settings_path != NULL &&
	    file_read(t.settings_path, &data, &len) == 0);
	CHECK_STR(data, "theme=system\n");
	free(data);
	tui_render(&t, &s);
	CHECK(s.fg == COLOR_DEFAULT && s.bg == COLOR_DEFAULT);
	CHECK(line_has(&s, 2, "System (dark background)"));
	CHECK(line_has(&s, t.lower_y + 1, "System keeps"));
	line = screen_line(&s, y);
	at = strstr(line, "orphaned");
	if (at != NULL)
		CHECK(s.back[y * s.cols + (size_t)(at - line)].attr.fg ==
		    COLOR_BRIGHT_RED);
	free(line);

	/* Right goes on to Light, whatever the background; Space goes round. */
	press_key(&t, KEY_RIGHT);
	CHECK(t.settings.theme == THEME_LIGHT && !tui_dark(&t));
	press_char(&t, " ");
	CHECK(t.settings.theme == THEME_DARK);
	press_key(&t, KEY_RIGHT);
	CHECK(t.settings.theme == THEME_DARK);
	press_char(&t, " ");
	CHECK(t.settings.theme == THEME_AUTO);
	press_key(&t, KEY_LEFT);
	CHECK(t.settings.theme == THEME_AUTO);
	/*
	 * A page, not a table: the section in bold, the chosen value only,
	 * the chosen row, no border between panels.
	 */
	tui_render(&t, &s);
	CHECK(line_has(&s, 1, "Appearance"));
	CHECK(s.back[1 * s.cols + 1].attr.style & STYLE_BOLD);
	CHECK(line_has(&s, 2, "Theme") && !line_has(&s, 2, "Light"));
	CHECK(s.back[2 * s.cols].attr.bg == theme_dark.select);
	CHECK(s.back[3 * s.cols].attr.bg == COLOR_DEFAULT);
	CHECK(t.sep_y == (size_t)-1 && !line_has(&s, 3, "\342\224\200"));
	CHECK(line_has(&s, 4, "Which theme is in use"));
	/* A click on the value takes the next one. */
	click_at(&t, t.value_x0, 2, 0, 1000);
	CHECK(t.settings.theme == THEME_SYSTEM);
	click_at(&t, t.value_x0 + 1, 2, 0, 3000);
	CHECK(t.settings.theme == THEME_LIGHT);
	click_at(&t, t.value_x0, 2, 0, 5000);
	CHECK(t.settings.theme == THEME_DARK);
	click_at(&t, 3, 2, 0, 7000);
	CHECK(t.option == OPTION_THEME && t.settings.theme == THEME_DARK);

	/* Settings come back with the program. */
	tui_free(&t);
	tui_init(&t);
	CHECK(t.settings.theme == THEME_DARK && t.screen == SCREEN_LIST);
	CHECK(tui_dark(&t));

	/* Dark paints the whole screen, in 256 colours or full. */
	tui_render(&t, &s);
	CHECK(s.fg == theme_dark.fg && s.bg == theme_dark.bg);
	data = screen_flush(&s, &len);
	snprintf(want, sizeof want, ";38;5;%d;48;5;%dm",
	    screen_nearest(0xd4d4d4), screen_nearest(0x1e1e1e));
	CHECK(strstr(data, want) != NULL);
	free(data);
	s.truecolor = 1;
	screen_invalidate(&s);
	tui_render(&t, &s);
	data = screen_flush(&s, &len);
	CHECK(strstr(data, ";38;2;212;212;212;48;2;30;30;30m") != NULL);
	free(data);
	s.truecolor = 0;

	/* Under NO_COLOR the theme cannot be changed and says why. */
	t.color = 0;
	press_char(&t, ",");
	press_char(&t, " ");
	CHECK(t.settings.theme == THEME_DARK && t.error != NULL &&
	    strstr(t.error, "NO_COLOR") != NULL);
	tui_render(&t, &s);
	CHECK(line_has(&s, 23, "NO_COLOR"));
	CHECK(s.back[22 * s.cols + t.buttons[0].x0].attr.fg ==
	    tui_theme(&t)->bar_grey);
	press_key(&t, KEY_ESC);
	CHECK(t.screen == SCREEN_LIST);
	CHECK(unlink(t.settings_path) == 0);

	screen_free(&s);
	tui_free(&t);
	setlocale(LC_CTYPE, "C");
}

static int lines_are(char **lines, size_t n, const char *const *want,
    size_t count)
{
	size_t i;

	if (n != count) {
		printf("unit: %zu lines, want %zu\n", n, count);
		return 0;
	}
	for (i = 0; i < n; i++)
		if (strcmp(lines[i], want[i]) != 0) {
			printf("unit: line %zu: \"%s\", want \"%s\"\n", i,
			    lines[i], want[i]);
			return 0;
		}
	return 1;
}

static void test_wrap(void)
{
	static const char *const indented[] = { "  aaa", "  bbb", "  ccc" };
	static const char *const cut[] = { "abcd", "efgh", "ij" };
	static const char *const blank[] = { "a", "", "b" };
	static const char *const deep[] = { "      x", "yyyy" };
	static const char *const wide[] = {
		"\346\227\245\346\234\254", "\350\252\236 a"
	};
	char **lines;
	size_t n;
	const char *text;

	text = "  aaa bbb ccc";
	lines = text_wrap(text, strlen(text), 8, &n);
	CHECK(lines_are(lines, n, indented, 3));
	text_lines_free(lines, n);
	text = "abcdefghij";
	lines = text_wrap(text, strlen(text), 4, &n);
	CHECK(lines_are(lines, n, cut, 3));
	text_lines_free(lines, n);
	text = "a\n\nb\n";
	lines = text_wrap(text, strlen(text), 4, &n);
	CHECK(lines_are(lines, n, blank, 3));
	text_lines_free(lines, n);
	/* An indent over half the width does not carry over. */
	text = "      x yyyy";
	lines = text_wrap(text, strlen(text), 8, &n);
	CHECK(lines_are(lines, n, deep, 2));
	text_lines_free(lines, n);
	/* Only what is asked for: the text need not end with its string. */
	lines = text_wrap("ab\ncd", 2, 8, &n);
	CHECK(n == 1 && strcmp(lines[0], "ab") == 0);
	text_lines_free(lines, n);
	lines = text_wrap("", 0, 8, &n);
	CHECK(n == 0);
	text_lines_free(lines, n);

	setlocale(LC_CTYPE, "en_US.UTF-8");
	if (MB_CUR_MAX == 1) {
		printf("unit: no en_US.UTF-8 locale, wide wrap checks skipped\n");
		return;
	}
	text = "\346\227\245\346\234\254\350\252\236 a";
	lines = text_wrap(text, strlen(text), 4, &n);
	CHECK(lines_are(lines, n, wide, 2));
	text_lines_free(lines, n);
	setlocale(LC_CTYPE, "C");
}

static void test_ui_state(void)
{
	struct ui_state st;
	char *text, *path, *dir;

	ui_state_default(&st);
	text = ui_state_text(&st);
	CHECK_STR(text, "sort=project\norder=normal\nsplit=500\nfilter=\n");
	free(text);
	/* Unknown keys and values change nothing; the filter keeps blanks. */
	text = "sort = size \norder=reverse\nsplit=1001\nsplit=x\nfoo=1\n"
	    "# sort=state\nfilter= a b \nselected=-a-b\nsort=nope\n";
	ui_state_parse(&st, text, strlen(text));
	CHECK(st.sort == 3 && st.reverse && st.split == 500);
	CHECK_STR(st.filter, " a b ");
	CHECK_STR(st.selected, "-a-b");
	text = "split=250\norder=normal\nselected=";
	ui_state_parse(&st, text, strlen(text));
	CHECK(st.split == 250 && !st.reverse && st.selected == NULL);
	free(st.filter);
	st.filter = xstrdup("x\ny");
	st.selected = xstrdup("-q");
	text = ui_state_text(&st);
	CHECK_STR(text, "sort=size\norder=normal\nsplit=250\nfilter=\n"
	    "selected=-q\n");
	free(text);
	ui_state_free(&st);

	path = ui_state_path("/h");
	CHECK(path != NULL && strlen(path) > 10 &&
	    strcmp(path + strlen(path) - 10, "/csm/state") == 0);
	free(path);
	CHECK(ui_state_path(NULL) == NULL || getenv("XDG_STATE_HOME") != NULL);
	dir = make_dir(work, "uistate");
	path = xjoin(dir, "none/state");
	CHECK(ui_state_load(path, &st) == 0 && st.sort == 1 &&
	    st.filter[0] == '\0' && st.selected == NULL);
	ui_state_free(&st);
	free(path);
	/* A directory where the file should be cannot be read. */
	CHECK(ui_state_load(dir, &st) != 0 && st.sort == 1);
	ui_state_free(&st);
	free(dir);
}

/* Restart keeps the view; help covers the screen it was opened from. */
static void test_remember(void)
{
	struct tui t;
	struct screen s;
	char *base, *config, *projects, *saved, *data, *file;
	const char *names[] = { "-a-one", "-b-two", "-c-three", "-d-four" };
	size_t i, len, top, narrow;

	saved = xstrdup(getenv("CLAUDE_CONFIG_DIR"));
	base = make_dir(work, "remember");
	config = make_dir(base, "config");
	projects = make_dir(config, "projects");
	for (i = 0; i < 4; i++)
		free(make_dir(projects, names[i]));
	setenv("CLAUDE_CONFIG_DIR", config, 1);
	setenv("LC_ALL", "en_US.UTF-8", 1);
	msg_init();
	if (setlocale(LC_CTYPE, "en_US.UTF-8") == NULL) {
		printf("unit: no en_US.UTF-8 locale, restart checks skipped\n");
		goto done;
	}

	/* Without a file: the defaults, nothing to save. */
	tui_init(&t);
	tui_set_claude(&t, 0, 0);
	CHECK(t.error == NULL && t.state_path != NULL);
	CHECK(t.sort == SORT_PROJECT && t.split == 500 && t.cursor == 0);
	CHECK(!tui_state_changed(&t));
	press_char(&t, "o");
	press_char(&t, "O");
	CHECK(tui_state_changed(&t));
	press_char(&t, "/");
	press_char(&t, "-");
	press_key(&t, KEY_ENTER);
	press_key(&t, KEY_END);
	t.split = 300;
	CHECK_STR(row_dir(&t, t.cursor), "-a-one");
	tui_save_state(&t);
	CHECK(t.error == NULL && !tui_state_changed(&t));
	CHECK(file_read(t.state_path, &data, &len) == 0);
	CHECK_STR(data, "sort=sessions\norder=reverse\nsplit=300\nfilter=-\n"
	    "selected=-a-one\n");
	free(data);
	tui_free(&t);

	/* All of it comes back with the program. */
	tui_init(&t);
	CHECK(t.error == NULL);
	CHECK(t.sort == SORT_SESSIONS && t.reverse && t.split == 300);
	CHECK_STR(t.filter, "-");
	CHECK_STR(row_dir(&t, t.cursor), "-a-one");
	CHECK(t.cursor == 3 && !tui_state_changed(&t));
	screen_init(&s, 80, 20, 1);
	tui_render(&t, &s);
	CHECK(line_has(&s, 0, "Filter: -"));
	CHECK(t.list_rows == 5);
	tui_free(&t);

	/* A directory that is gone leaves the first one selected. */
	file = xjoin(projects, "-a-one");
	CHECK(rmdir(file) == 0);
	free(file);
	tui_init(&t);
	CHECK(t.cursor == 0 && t.view_count == 3);
	CHECK(!tui_state_changed(&t));
	tui_free(&t);

	/* A state that cannot be read or written says so in one sentence. */
	file = ui_state_path(getenv("HOME"));
	CHECK(unlink(file) == 0 && mkdir(file, 0700) == 0);
	tui_init(&t);
	CHECK(t.error != NULL && strstr(t.error, "remembered view") != NULL);
	CHECK(t.sort == SORT_PROJECT);
	CHECK(rmdir(file) == 0);
	free(t.state_path);
	t.state_path = xjoin(projects, "-b-two/memory/x/state");
	write_file(projects, "-b-two/memory", "");
	press_char(&t, "o");
	free(t.error);
	t.error = NULL;
	tui_save_state(&t);
	CHECK(t.error != NULL && strstr(t.error, "Cannot remember") != NULL);
	CHECK(!tui_state_changed(&t));
	tui_free(&t);
	free(file);

	/* Help: wrapped to the window, scrolled by keys and the wheel. */
	tui_init(&t);
	tui_set_claude(&t, 0, 0);
	screen_resize(&s, 60, 12);
	press_char(&t, "?");
	CHECK(t.screen == SCREEN_HELP);
	tui_render(&t, &s);
	CHECK(t.help_rows == 9 && t.help_width == 58 && t.help_count > 60);
	for (i = 0; i < t.help_count; i++)
		CHECK(text_width(t.help_lines[i]) <= 58);
	CHECK(line_has(&s, 1, "csm \342\200\224 manages"));
	CHECK(line_has(&s, 10, "Esc Close"));
	CHECK(line_has(&s, 11, "PgUp PgDn scroll"));
	press_key(&t, KEY_DOWN);
	CHECK(t.help_top == 1);
	press_key(&t, KEY_PAGE_DOWN);
	CHECK(t.help_top == 9);
	press_key(&t, KEY_END);
	top = t.help_count - 9;
	CHECK(t.help_top == top);
	press_key(&t, KEY_DOWN);
	CHECK(t.help_top == top);
	tui_render(&t, &s);
	CHECK(line_has(&s, 9, "3 Claude Code"));
	press_key(&t, KEY_HOME);
	mouse_at(&t, MOUSE_WHEEL_DOWN, 5, 4, 0, 0);
	CHECK(t.help_top == 3);
	mouse_at(&t, MOUSE_WHEEL_UP, 5, 10, 0, 0);
	CHECK(t.help_top == 3);
	press_key(&t, KEY_PAGE_UP);
	CHECK(t.help_top == 0);
	/* A wider window wraps again, into fewer lines. */
	narrow = t.help_count;
	screen_resize(&s, 100, 12);
	tui_render(&t, &s);
	CHECK(t.help_width == 98 && t.help_count < narrow);
	for (i = 0; i < t.help_count; i++)
		CHECK(text_width(t.help_lines[i]) <= 98);
	click_at(&t, t.buttons[0].x0, 10, 0, 0);
	CHECK(t.screen == SCREEN_LIST);
	/* From the trash and the settings, and back to them. */
	press_char(&t, "t");
	press_char(&t, "h");
	CHECK(t.screen == SCREEN_HELP);
	press_char(&t, "?");
	CHECK(t.screen == SCREEN_TRASH);
	press_key(&t, KEY_ESC);
	press_char(&t, ",");
	press_char(&t, "?");
	CHECK(t.screen == SCREEN_HELP);
	press_key(&t, KEY_ESC);
	CHECK(t.screen == SCREEN_SETTINGS);
	press_char(&t, "?");
	press_char(&t, "q");
	CHECK(t.quit);
	screen_free(&s);
	tui_free(&t);
	setlocale(LC_CTYPE, "C");
done:
	setenv("CLAUDE_CONFIG_DIR", saved, 1);
	free(saved);
	free(projects);
	free(config);
	free(base);
}

int main(int argc, char **argv)
{
	char *home, *config;

	if (argc != 2) {
		fprintf(stderr, "usage: unit WORKDIR\n");
		return 2;
	}
	work = realpath(argv[1], NULL);
	if (work == NULL) {
		fprintf(stderr, "unit: %s: %s\n", argv[1], strerror(errno));
		return 2;
	}
	sleeper = realpath("build/csm-fake-claude", NULL);
	/* Never the user's data: HOME and the config live in the work dir. */
	home = make_dir(work, "home");
	config = make_dir(home, ".claude");
	setenv("HOME", home, 1);
	setenv("CLAUDE_CONFIG_DIR", config, 1);
	CHECK(chdir(work) == 0);

	test_encode();
	test_normalize();
	test_logical_physical();
	test_prefix();
	test_path_parts();
	test_process();
	test_json();
	test_json_scan();
	test_json_encode();
	test_rewrite_session();
	test_rewrite_index();
	test_rewrite_config();
	test_rewrite_files();
	test_session();
	test_format();
	test_state();
	test_session_info();
	test_version();
	test_inventory();
	test_cli();
	test_msg();
	test_trash_config();
	test_trash_files();
	test_trash_flow();
	test_field();
	test_github();
	test_report();
	test_keys();
	test_screen();
	test_tui_columns();
	test_tui();
	test_tui_actions();
	test_settings();
	test_wrap();
	test_ui_state();
	test_remember();

	printf("unit: %d checks, %d failed\n", test_checks, test_failures);
	free(home);
	free(config);
	free(work);
	free(sleeper);
	return test_failures != 0;
}
